def k8s_get_contexts(status=None, context=None, cluster=None, user=None, server=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(x):
        try:
            return len(json.dumps(x, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((now + "|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]

    def _b64url_encode(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        return json.loads(raw.decode("utf-8"))

    def _pick_api_key(api_keys):
        # Ambient auth: choose an active key that can serve read-only tools.
        # Must be callable even without explicit credential params.
        actives = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not actives:
            return None
        # Prefer non-revoked; any active is fine for reads
        return actives[0]

    def _rate_limit_check_and_increment(api_key_row, context_id=None):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []

        def _floor_window(dt, window_seconds):
            epoch = int(dt.timestamp())
            ws = (epoch // window_seconds) * window_seconds
            return datetime.datetime.utcfromtimestamp(ws).replace(microsecond=0)

        dt_now = datetime.datetime.utcnow()
        limits = [
            (60, int(api_key_row.get("rate_limit_rpm", 0)), "rpm"),
            (1, int(api_key_row.get("burst_limit", 0)), "burst"),
        ]
        projected = {}
        for window_seconds, limit_value, _tag in limits:
            if limit_value <= 0:
                return _err("VALIDATION_ERROR", "API key has invalid rate limit configuration.", error_code="VALIDATION_ERROR")
            wstart = _floor_window(dt_now, window_seconds).isoformat() + "Z"

            # bucket key: global per-key (context_id null) for all tools
            match_idx = None
            for i, c in enumerate(counters):
                if not isinstance(c, dict):
                    continue
                if c.get("api_key_id") == api_key_row.get("id") and c.get("context_id") is None and c.get("window_seconds") == window_seconds and c.get("window_start_at") == wstart:
                    match_idx = i
                    break
            if match_idx is None:
                newc = {
                    "id": _new_id("rlc"),
                    "api_key_id": api_key_row.get("id"),
                    "context_id": None,
                    "window_start_at": wstart,
                    "window_seconds": window_seconds,
                    "count": 0,
                    "created_at": now,
                    "updated_at": now,
                }
                counters.append(newc)
                match_idx = len(counters) - 1

            projected_count = int(counters[match_idx].get("count", 0)) + 1
            projected[window_seconds] = (match_idx, projected_count, limit_value)

        # enforce first, then increment if allowed
        for window_seconds, (idx, proj, limit_value) in projected.items():
            if proj > limit_value:
                return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit_value)

        for window_seconds, (idx, proj, limit_value) in projected.items():
            counters[idx]["count"] = proj
            counters[idx]["updated_at"] = now
        _save("rate_limit_counters.json", counters)
        return None

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    api_key = _pick_api_key(api_keys)
    if api_key is None:
        # No usable auth context exists at all
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.", error_code="UNAUTHORIZED")

    # Validate inputs
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", error_code="VALIDATION_ERROR")
    for nm, val in (("context", context), ("cluster", cluster), ("user", user), ("server", server), ("cursor", cursor), ("sort", sort), ("order", order)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"Invalid type for {nm}.", error_code="VALIDATION_ERROR")
        if isinstance(val, str) and nm in ("context", "cluster", "user", "server") and val == "":
            return _err("VALIDATION_ERROR", f"{nm} must not be empty when provided.", error_code="VALIDATION_ERROR")

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.", error_code="VALIDATION_ERROR")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit out of range (1-200).", error_code="VALIDATION_ERROR")
        limit_i = limit

    if sort is None:
        sort_f = "created_at"
    else:
        if sort not in ("created_at", "updated_at", "last_validated_at", "context_name", "cluster_name", "status"):
            return _err("VALIDATION_ERROR", "Invalid sort field.", error_code="VALIDATION_ERROR")
        sort_f = sort

    if order is None:
        order_s = "asc"
    else:
        if order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "Invalid order value.", error_code="VALIDATION_ERROR")
        order_s = order

    # Rate limit before doing any operation bookkeeping
    rl_err = _rate_limit_check_and_increment(api_key, context_id=None)
    if rl_err:
        # log operation as failed due to rate limit
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list): ops = []
        op_id = _new_id("op")
        params = {"status": status, "context": context, "cluster": cluster, "user": user, "server": server, "limit": limit, "cursor": cursor, "sort": sort, "order": order}
        op = {
            "id": op_id,
            "api_key_id": api_key.get("id"),
            "context_id": next((c.get("id") for c in _load("k8s_contexts.json") if isinstance(c, dict)), None) or "unknown",
            "tool_name": "k8s_get_contexts",
            "status": "failed",
            "is_mutation": False,
            "requested_namespace": None,
            "resource_type": None,
            "resource_name": None,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": _json_size(params),
            "response_size_bytes": None,
            "error_code": rl_err["error"].get("error_code"),
            "error_message": rl_err["error"].get("message"),
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return rl_err

    # Create operation row (context_id is not meaningful here; store null-equivalent by picking none)
    contexts_all = _load("k8s_contexts.json")
    if not isinstance(contexts_all, list):
        contexts_all = []
    any_context_id = next((c.get("id") for c in contexts_all if isinstance(c, dict) and c.get("id")), None)
    ops = _load("k8s_operations.json")
    if not isinstance(ops, list): ops = []
    op_id = _new_id("op")
    params = {"status": status, "context": context, "cluster": cluster, "user": user, "server": server, "limit": limit, "cursor": cursor, "sort": sort, "order": order}
    op = {
        "id": op_id,
        "api_key_id": api_key.get("id"),
        "context_id": any_context_id or "unknown",
        "tool_name": "k8s_get_contexts",
        "status": "queued",
        "is_mutation": False,
        "requested_namespace": None,
        "resource_type": None,
        "resource_name": None,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": _json_size(params),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    # Transition queued->running
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = now
            o["updated_at"] = now
            break
    _save("k8s_operations.json", ops)

    # Apply filters
    rows = [c for c in contexts_all if isinstance(c, dict) and c.get("status") in ("active", "disabled", "error")]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if context is not None:
        rows = [c for c in rows if c.get("context_name") == context]
    if cluster is not None:
        rows = [c for c in rows if c.get("cluster_name") == cluster]
    if user is not None:
        rows = [c for c in rows if c.get("user_name") == user]
    if server is not None:
        rows = [c for c in rows if c.get("server") == server]

    # Sort
    reverse = (order_s == "desc")
    def _sort_key(c):
        v = c.get(sort_f)
        # None-safe: place None last for asc, first for desc
        if v is None:
            return (1, "")
        return (0, str(v))
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor contains {"offset": int}
    offset = 0
    if cursor is not None:
        try:
            cur = _b64url_decode(cursor)
            if not isinstance(cur, dict) or "offset" not in cur or not isinstance(cur["offset"], int) or cur["offset"] < 0:
                # fail validation
                # mark op failed
                for o in ops:
                    if o.get("id") == op_id:
                        o["status"] = "failed"
                        o["error_code"] = "VALIDATION_ERROR"
                        o["error_message"] = "Invalid cursor."
                        o["finished_at"] = now
                        o["updated_at"] = now
                        break
                _save("k8s_operations.json", ops)
                return _err("VALIDATION_ERROR", "Invalid cursor.", error_code="VALIDATION_ERROR")
            offset = cur["offset"]
        except Exception:
            for o in ops:
                if o.get("id") == op_id:
                    o["status"] = "failed"
                    o["error_code"] = "VALIDATION_ERROR"
                    o["error_message"] = "Invalid cursor."
                    o["finished_at"] = now
                    o["updated_at"] = now
                    break
            _save("k8s_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid cursor.", error_code="VALIDATION_ERROR")

    page = rows[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _b64url_encode({"offset": next_offset}) if has_more else None

    body = {
        "contexts": page,
        "meta": {"total": len(rows), "limit": limit_i, "has_more": has_more, "next_cursor": next_cursor},
        "operation_id": op_id,
    }

    # Store result row
    results = _load("k8s_operation_results.json")
    if not isinstance(results, list): results = []
    res_id = _new_id("res")
    result_row = {
        "id": res_id,
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": {"contexts": page, "meta": body["meta"]},
        "truncated": False,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now,
    }
    results.append(result_row)
    _save("k8s_operation_results.json", results)

    # Finish operation running->succeeded
    now2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops = _load("k8s_operations.json")
    if not isinstance(ops, list): ops = []
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["finished_at"] = now2
            o["updated_at"] = now2
            o["response_size_bytes"] = _json_size(body)
            break
    _save("k8s_operations.json", ops)

    return body

def k8s_get_namespaces(context, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(x):
        try:
            return len(json.dumps(x, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((now + "|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]

    def _pick_api_key(api_keys, context_id, requested_namespace=None, is_mutation=False):
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            if is_mutation and not k.get("allow_mutations", False):
                continue
            allowed_ctx = k.get("allowed_context_ids", None)
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or context_id not in allowed_ctx:
                    continue
            allowed_ns = k.get("allowed_namespaces", None)
            if allowed_ns is not None and requested_namespace is not None:
                if not isinstance(allowed_ns, list) or requested_namespace not in allowed_ns:
                    continue
            return k
        return None

    def _rate_limit_check_and_increment(api_key_row):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        dt_now = datetime.datetime.utcnow()

        def _floor_window(dt, window_seconds):
            epoch = int(dt.timestamp())
            ws = (epoch // window_seconds) * window_seconds
            return datetime.datetime.utcfromtimestamp(ws).replace(microsecond=0)

        for window_seconds, limit_value in ((60, api_key_row.get("rate_limit_rpm")), (1, api_key_row.get("burst_limit"))):
            if not isinstance(limit_value, int) or limit_value <= 0:
                return _err("VALIDATION_ERROR", "API key has invalid rate limit configuration.", error_code="VALIDATION_ERROR")
            wstart = _floor_window(dt_now, window_seconds).isoformat() + "Z"
            idx = None
            for i, c in enumerate(counters):
                if isinstance(c, dict) and c.get("api_key_id") == api_key_row.get("id") and c.get("context_id") is None and c.get("window_seconds") == window_seconds and c.get("window_start_at") == wstart:
                    idx = i
                    break
            if idx is None:
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": api_key_row.get("id"),
                    "context_id": None,
                    "window_start_at": wstart,
                    "window_seconds": window_seconds,
                    "count": 0,
                    "created_at": now,
                    "updated_at": now,
                })
                idx = len(counters) - 1
            proj = int(counters[idx].get("count", 0)) + 1
            if proj > limit_value:
                return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit_value)

        # increment after checks
        for window_seconds, _limit_value in ((60, api_key_row.get("rate_limit_rpm")), (1, api_key_row.get("burst_limit"))):
            wstart = _floor_window(dt_now, window_seconds).isoformat() + "Z"
            for c in counters:
                if isinstance(c, dict) and c.get("api_key_id") == api_key_row.get("id") and c.get("context_id") is None and c.get("window_seconds") == window_seconds and c.get("window_start_at") == wstart:
                    c["count"] = int(c.get("count", 0)) + 1
                    c["updated_at"] = now
                    break
        _save("rate_limit_counters.json", counters)
        return None

    # Validate inputs
    if not isinstance(context, str):
        return _err("VALIDATION_ERROR", "context must be a string.", error_code="VALIDATION_ERROR")
    if context.strip() == "":
        return _err("VALIDATION_ERROR", "context is required.", error_code="VALIDATION_ERROR")

    contexts = _load("k8s_contexts.json")
    if not isinstance(contexts, list):
        contexts = []
    ctx = next((c for c in contexts if isinstance(c, dict) and c.get("context_name") == context), None)
    if ctx is None:
        return _err("NOT_FOUND", "Context not registered.", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("CONFLICT", "Context is not active.", error_code="CONTEXT_DISABLED", status=ctx.get("status"))

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    api_key = _pick_api_key(api_keys, ctx.get("id"), requested_namespace=None, is_mutation=False)
    if api_key is None:
        # determine forbidden vs unauthorized
        any_active = any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys)
        if any_active:
            return _err("UNAUTHORIZED", "No active API key is permitted to access this context.", error_code="FORBIDDEN_CONTEXT")
        return _err("UNAUTHORIZED", "No active API key available.", error_code="UNAUTHORIZED")

    rl_err = _rate_limit_check_and_increment(api_key)
    if rl_err:
        # log failed operation
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list): ops = []
        op_id = _new_id("op")
        params = {"context": context}
        ops.append({
            "id": op_id,
            "api_key_id": api_key.get("id"),
            "context_id": ctx.get("id"),
            "tool_name": "k8s_get_namespaces",
            "status": "failed",
            "is_mutation": False,
            "requested_namespace": None,
            "resource_type": None,
            "resource_name": None,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": _json_size(params),
            "response_size_bytes": None,
            "error_code": rl_err["error"].get("error_code"),
            "error_message": rl_err["error"].get("message"),
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("k8s_operations.json", ops)
        return rl_err

    # create op queued
    ops = _load("k8s_operations.json")
    if not isinstance(ops, list): ops = []
    op_id = _new_id("op")
    params = {"context": context}
    ops.append({
        "id": op_id,
        "api_key_id": api_key.get("id"),
        "context_id": ctx.get("id"),
        "tool_name": "k8s_get_namespaces",
        "status": "queued",
        "is_mutation": False,
        "requested_namespace": None,
        "resource_type": None,
        "resource_name": None,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": _json_size(params),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("k8s_operations.json", ops)

    # queued->running
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = now
            o["updated_at"] = now
            break
    _save("k8s_operations.json", ops)

    # Live cluster not available offline: serve minimal observable behavior
    # Return a stable, empty list (read with no matches is not an error)
    namespaces = []

    body = {"namespaces": namespaces, "operation_id": op_id}

    results = _load("k8s_operation_results.json")
    if not isinstance(results, list): results = []
    results.append({
        "id": _new_id("res"),
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": {"namespaces": namespaces},
        "truncated": False,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("k8s_operation_results.json", results)

    now2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops = _load("k8s_operations.json")
    if not isinstance(ops, list): ops = []
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["finished_at"] = now2
            o["updated_at"] = now2
            o["response_size_bytes"] = _json_size(body)
            break
    _save("k8s_operations.json", ops)

    return body

