def k8s_get_pod_logs(context, namespace, pod, previousContainer=False, sinceDuration=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_duration(s):
        # Accept kubectl-like subset: <int>(s|m|h|d). Reject others.
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE"
        ss = s.strip()
        if ss == "":
            return "EMPTY"
        m = re.fullmatch(r"(\d+)([smhd])", ss)
        if not m:
            return "FORMAT"
        val = int(m.group(1))
        unit = m.group(2)
        mult = {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
        seconds = val * mult
        if seconds < 0:
            return "RANGE"
        return seconds

    # Validate inputs
    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context is required and must be a non-empty string")
    if not isinstance(namespace, str) or not namespace.strip():
        return _err("VALIDATION_ERROR", "namespace is required and must be a non-empty string")
    if not isinstance(pod, str) or not pod.strip():
        return _err("VALIDATION_ERROR", "pod is required and must be a non-empty string")
    if previousContainer is None:
        previousContainer = False
    if not isinstance(previousContainer, bool):
        return _err("VALIDATION_ERROR", "previousContainer must be a boolean")
    dur = _parse_duration(sinceDuration)
    if dur in ("TYPE", "EMPTY", "FORMAT", "RANGE"):
        return _err("VALIDATION_ERROR", "sinceDuration is invalid")

    # Load datastore
    contexts = _load("k8s_contexts.json")
    keys = _load("api_keys.json")
    ops = _load("k8s_operations.json")
    results = _load("k8s_operation_results.json")
    counters = _load("rate_limit_counters.json")

    # Helper: background cleanup of expired results + cascade deletes for missing operations
    def _cleanup_expired():
        nonlocal results
        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        op_ids = set(o.get("id") for o in ops if isinstance(o, dict))
        new_results = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            oid = r.get("operation_id")
            if oid not in op_ids:
                changed = True
                continue
            exp = r.get("retention_expires_at")
            if exp:
                try:
                    exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    # If malformed, keep (don't destroy data unexpectedly)
                    new_results.append(r)
                    continue
                if exp_dt <= now_dt:
                    changed = True
                    continue
            new_results.append(r)
        if changed:
            results = new_results
            _save("k8s_operation_results.json", results)

    _cleanup_expired()

    # Resolve context
    ctx = None
    for c in contexts:
        if isinstance(c, dict) and c.get("context_name") == context:
            ctx = c
            break
    if not ctx:
        # No operation should be created if we can't resolve context; still record dynamics? Schema says every tool invocation creates an operation row.
        # But business rule 1 says fail with CONTEXT_NOT_FOUND; we create an operation with a best-effort context_id placeholder? Not allowed (fk).
        # So we must fail without creating operation (as we cannot satisfy FK constraints).
        return _err("NOT_FOUND", "context is not registered", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "context is not active", error_code="CONTEXT_DISABLED")

    # Resolve an API key ambiently: any active key that can access this context/namespace and allows read.
    # Reads do not require allow_mutations.
    active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    chosen_key = None
    for k in active_keys:
        aci = k.get("allowed_context_ids", None)
        if aci is not None:
            if not isinstance(aci, list) or ctx.get("id") not in aci:
                continue
        ans = k.get("allowed_namespaces", None)
        if ans is not None:
            if not isinstance(ans, list) or namespace not in ans:
                continue
        chosen_key = k
        break
    if not chosen_key:
        # Distinguish forbidden vs unauthorized: if there exists active key but none allows context/ns => UNAUTHORIZED/FORBIDDEN.
        any_active = bool(active_keys)
        if any_active:
            # Determine which constraint is violated most directly
            for k in active_keys:
                aci = k.get("allowed_context_ids", None)
                if aci is not None and isinstance(aci, list) and ctx.get("id") in aci:
                    return _err("UNAUTHORIZED", "namespace is not permitted for this key", error_code="FORBIDDEN_NAMESPACE")
            return _err("UNAUTHORIZED", "context is not permitted for this key", error_code="FORBIDDEN_CONTEXT")
        return _err("UNAUTHORIZED", "no active API key available to authorize this request")

    api_key_id = chosen_key.get("id")
    context_id = ctx.get("id")

    # Rate limiting: increment counters for 60s and 1s windows; reject if projected exceeds.
    def _bucket_start(dt, window_seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % window_seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    projected = {}
    windows = [60, 1]
    for w in windows:
        ws = _bucket_start(now_dt, w)
        # find existing global-per-key bucket (context_id = None)
        b = None
        for row in counters:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") == api_key_id and row.get("context_id") is None and row.get("window_seconds") == w and row.get("window_start_at") == ws:
                b = row
                break
        if b is None:
            b = {
                "id": _new_id("rl"),
                "api_key_id": api_key_id,
                "context_id": None,
                "window_start_at": ws,
                "window_seconds": w,
                "count": 0,
                "created_at": now,
                "updated_at": now,
            }
            counters.append(b)
        projected[w] = int(b.get("count", 0)) + 1

    rpm = chosen_key.get("rate_limit_rpm")
    burst = chosen_key.get("burst_limit")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
        return _err("UNAUTHORIZED", "api key has invalid rate_limit_rpm configuration")
    if not isinstance(burst, int) or burst < 1 or burst > 10000:
        return _err("UNAUTHORIZED", "api key has invalid burst_limit configuration")

    if projected[60] > rpm or projected[1] > burst:
        # Do not increment counters on rejected request (projected exceed)
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="RATE_LIMITED", retry_after_seconds=1)

    # Apply increments and persist
    for w in windows:
        ws = _bucket_start(now_dt, w)
        for row in counters:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") == api_key_id and row.get("context_id") is None and row.get("window_seconds") == w and row.get("window_start_at") == ws:
                row["count"] = projected[w]
