    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- validation ----
    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(namespace, str) or not namespace.strip():
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(resource_type, str) or not resource_type.strip():
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", error_code="VALIDATION_ERROR")

    ctx_name = context.strip()
    ns = namespace.strip()
    rtype = resource_type.strip()
    rname = name.strip()

    # Basic identifier validation (DNS label-ish for workload names; namespace is DNS label)
    dns_label = re.compile(r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$")
    if len(ns) > 63 or not dns_label.match(ns):
        return _err("VALIDATION_ERROR", "namespace is not a valid DNS label", error_code="VALIDATION_ERROR")
    if len(rname) > 253 or not re.match(r"^[a-z0-9]([-.a-z0-9]*[a-z0-9])?$", rname):
        return _err("VALIDATION_ERROR", "name is not a valid Kubernetes resource name", error_code="VALIDATION_ERROR")

    supported = {"deployment", "daemonset", "statefulset"}
    rtype_norm = rtype.lower()
    if rtype_norm.endswith("s"):
        rtype_norm = rtype_norm[:-1]
    if rtype_norm not in supported:
        return _err("VALIDATION_ERROR", "unsupported resource_type for rollout restart", error_code="VALIDATION_ERROR")

    # ---- load store ----
    contexts = _load("k8s_contexts.json")
    keys = _load("api_keys.json")
    ops = _load("k8s_operations.json")
    results = _load("k8s_operation_results.json")
    counters = _load("rate_limit_counters.json")

    # ---- resolve context ----
    ctx = next((c for c in contexts if isinstance(c, dict) and c.get("context_name") == ctx_name), None)
    if not ctx:
        return _err("NOT_FOUND", "context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("CONFLICT", "context is not active", error_code="CONTEXT_DISABLED", context_status=ctx.get("status"))

    # ---- resolve an API key (ambient authentication) that can serve this call ----
    # Pick a key that is active, allows mutations, allows context + namespace, and is within rate limits.
    candidate_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    if not candidate_keys:
        return _err("UNAUTHORIZED", "no active API key available", error_code="UNAUTHORIZED")

    # helper: id generator
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _iso_floor(dt, seconds):
        # floor to bucket boundary relative to epoch
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _get_bucket(api_key_id, context_id, window_seconds, bucket_start_iso):
        for b in counters:
            if not isinstance(b, dict):
                continue
            if b.get("api_key_id") != api_key_id:
                continue
            if b.get("context_id") != context_id:
                continue
            if b.get("window_seconds") != window_seconds:
                continue
            if b.get("window_start_at") != bucket_start_iso:
                continue
            return b
        return None

    def _projected_with_increment(api_key_id, context_id, window_seconds, limit):
        dt = datetime.datetime.utcnow().replace(microsecond=0)
        bucket_start_iso = _iso_floor(dt, window_seconds)
        b = _get_bucket(api_key_id, context_id, window_seconds, bucket_start_iso)
        current = int(b.get("count", 0)) if b else 0
        projected = current + 1
        return projected, bucket_start_iso, b

    chosen_key = None
    rate_check_info = None

    for k in candidate_keys:
        # mutations allowed?
        if k.get("allow_mutations") is not True:
            continue
        # context allowlist
        allowed_ctx = k.get("allowed_context_ids", None)
        if allowed_ctx is not None:
            if not isinstance(allowed_ctx, list) or ctx.get("id") not in allowed_ctx:
                continue
