                continue

        # rate limits
        rpm = k.get("rate_limit_rpm")
        burst = k.get("burst_limit")
        if not isinstance(rpm, int) or not (1 <= rpm <= 60000):
            continue
        if not isinstance(burst, int) or not (1 <= burst <= 10000):
            continue

        proj60, start60, bucket60 = _projected_with_increment(k["id"], None, 60, rpm)
        if proj60 > rpm:
            continue
        proj1, start1, bucket1 = _projected_with_increment(k["id"], None, 1, burst)
        if proj1 > burst:
            continue

        chosen_key = k
        rate_check_info = (proj60, start60, bucket60, proj1, start1, bucket1)
        break

