        "resource_type": rtype_norm,
        "resource_name": rname,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": max(0, int(req_size)),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    def _update_op_status(op_row, new_status, error_code=None, error_message=None):
        old = op_row.get("status")
        allowed = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        if old not in allowed or new_status not in allowed[old]:
            return False
        op_row["status"] = new_status
        op_row["updated_at"] = now
        if new_status == "running":
            op_row["started_at"] = op_row.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op_row["finished_at"] = now
        if error_code is not None:
            op_row["error_code"] = error_code
        if error_message is not None:
            op_row["error_message"] = error_message
        return True

    if not _update_op_status(op, "running"):
        op["error_code"] = "INVALID_TRANSITION"
        op["error_message"] = "illegal operation status transition"
        op["status"] = "failed"
        op["finished_at"] = now
        _save("k8s_operations.json", ops)
        return _err("INVALID_TRANSITION", "illegal operation status transition", error_code="INVALID_TRANSITION", operation=op)

    payload = {
        "action": "rollout_resume",
        "resource_type": rtype_norm,
        "namespace": ns,
        "name": rname,
        "context": ctx_name,
        "message": f"Rollout resumed for {rtype_norm}/{rname} in namespace {ns}."
    }
    res_id = _new_id("res")
    resp_bytes = len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    res = {
        "id": res_id,
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": payload,
        "truncated": False,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res)
    _save("k8s_operation_results.json", results)

    _update_op_status(op, "succeeded")
    op["response_size_bytes"] = max(0, int(resp_bytes))
    _save("k8s_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "result": res, "meta": {"latency_ms": latency_ms}}

def k8s_scale_resource(context, namespace, resource_type, name, replicas, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(namespace, str) or not namespace.strip():
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(resource_type, str) or not resource_type.strip():
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(replicas, int):
        return _err("VALIDATION_ERROR", "replicas must be an integer", error_code="VALIDATION_ERROR")
    if replicas < 0 or replicas > 10000:
        return _err("VALIDATION_ERROR", "replicas must be between 0 and 10000 inclusive", error_code="INVALID_REPLICAS")

    ctx_name = context.strip()
    ns = namespace.strip()
    rtype = resource_type.strip()
    rname = name.strip()

    dns_label = re.compile(r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$")
    if len(ns) > 63 or not dns_label.match(ns):
        return _err("VALIDATION_ERROR", "namespace is not a valid DNS label", error_code="VALIDATION_ERROR")
    if len(rname) > 253 or not re.match(r"^[a-z0-9]([-.a-z0-9]*[a-z0-9])?$", rname):
        return _err("VALIDATION_ERROR", "name is not a valid Kubernetes resource name", error_code="VALIDATION_ERROR")

    supported = {"deployment", "statefulset", "replicaset"}
    rtype_norm = rtype.lower()
    if rtype_norm.endswith("s"):
        rtype_norm = rtype_norm[:-1]
    if rtype_norm not in supported:
        return _err("VALIDATION_ERROR", "unsupported resource_type for scale", error_code="VALIDATION_ERROR")

    contexts = _load("k8s_contexts.json")
    keys = _load("api_keys.json")
    ops = _load("k8s_operations.json")
    results = _load("k8s_operation_results.json")
    counters = _load("rate_limit_counters.json")

    ctx = next((c for c in contexts if isinstance(c, dict) and c.get("context_name") == ctx_name), None)
    if not ctx:
        return _err("NOT_FOUND", "context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("CONFLICT", "context is not active", error_code="CONTEXT_DISABLED", context_status=ctx.get("status"))

    candidate_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    if not candidate_keys:
        return _err("UNAUTHORIZED", "no active API key available", error_code="UNAUTHORIZED")

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _iso_floor(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _get_bucket(api_key_id, context_id, window_seconds, bucket_start_iso):
        for b in counters:
            if not isinstance(b, dict):
                continue
            if b.get("api_key_id") != api_key_id:
                continue
            if b.get("context_id") != context_id:
                continue
            if b.get("window_seconds") != window_seconds:
                continue
            if b.get("window_start_at") != bucket_start_iso:
                continue
            return b
        return None

    def _projected_with_increment(api_key_id, context_id, window_seconds, limit):
        dt = datetime.datetime.utcnow().replace(microsecond=0)
        bucket_start_iso = _iso_floor(dt, window_seconds)
        b = _get_bucket(api_key_id, context_id, window_seconds, bucket_start_iso)
        current = int(b.get("count", 0)) if b else 0
        projected = current + 1
        return projected, bucket_start_iso, b

    chosen_key = None
    rate_check_info = None
    for k in candidate_keys:
        if k.get("allow_mutations") is not True:
            continue
        allowed_ctx = k.get("allowed_context_ids", None)
        if allowed_ctx is not None:
            if not isinstance(allowed_ctx, list) or ctx.get("id") not in allowed_ctx:
                continue
        allowed_ns = k.get("allowed_namespaces", None)
        if allowed_ns is not None:
            if not isinstance(allowed_ns, list) or ns not in allowed_ns:
                continue
        rpm = k.get("rate_limit_rpm")
        burst = k.get("burst_limit")
        if not isinstance(rpm, int) or not (1 <= rpm <= 60000):
            continue
        if not isinstance(burst, int) or not (1 <= burst <= 10000):
            continue
        proj60, start60, bucket60 = _projected_with_increment(k["id"], None, 60, rpm)
        if proj60 > rpm:
            continue
        proj1, start1, bucket1 = _projected_with_increment(k["id"], None, 1, burst)
        if proj1 > burst:
            continue
        chosen_key = k
        rate_check_info = (proj60, start60, bucket60, proj1, start1, bucket1)
        break

    if not chosen_key:
        any_mut_key = any(k.get("status") == "active" and k.get("allow_mutations") is True for k in keys if isinstance(k, dict))
        if not any_mut_key:
            return _err("UNAUTHORIZED", "mutations are disabled for available keys", error_code="MUTATIONS_DISABLED")
        any_allowed = False
        for k in keys:
            if not isinstance(k, dict) or k.get("status") != "active" or k.get("allow_mutations") is not True:
                continue
            allowed_ctx = k.get("allowed_context_ids", None)
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx.get("id") not in allowed_ctx):
                continue
            allowed_ns = k.get("allowed_namespaces", None)
            if allowed_ns is not None and (not isinstance(allowed_ns, list) or ns not in allowed_ns):
                continue
            any_allowed = True
            break
        if not any_allowed:
            return _err("UNAUTHORIZED", "not permitted for this context/namespace", error_code="FORBIDDEN_CONTEXT_OR_NAMESPACE")
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="RATE_LIMITED")

    api_key_id = chosen_key["id"]
    proj60, start60, bucket60, proj1, start1, bucket1 = rate_check_info

    def _touch_bucket(bucket, api_key_id, context_id, window_seconds, window_start_iso):
        if bucket is None:
            bucket = {
                "id": _new_id("rlc"),
                "api_key_id": api_key_id,
                "context_id": context_id,
                "window_start_at": window_start_iso,
                "window_seconds": window_seconds,
                "count": 0,
                "created_at": now,
                "updated_at": now
            }
            counters.append(bucket)
        bucket["count"] = int(bucket.get("count", 0)) + 1
        bucket["updated_at"] = now
        return bucket

    _touch_bucket(bucket60, api_key_id, None, 60, start60)
    _touch_bucket(bucket1, api_key_id, None, 1, start1)
    _save("rate_limit_counters.json", counters)

    op_id = _new_id("op")
    params = {"context": context, "namespace": namespace, "resource_type": resource_type, "name": name, "replicas": replicas}
    req_size = len(json.dumps(params, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    op = {
        "id": op_id,
        "api_key_id": api_key_id,
        "context_id": ctx["id"],
        "tool_name": "k8s_scale_resource",
        "status": "queued",
        "is_mutation": True,
        "requested_namespace": ns,
        "resource_type": rtype_norm,
        "resource_name": rname,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": max(0, int(req_size)),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    def _update_op_status(op_row, new_status, error_code=None, error_message=None):
        old = op_row.get("status")
        allowed = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        if old not in allowed or new_status not in allowed[old]:
            return False
        op_row["status"] = new_status
        op_row["updated_at"] = now
        if new_status == "running":
            op_row["started_at"] = op_row.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op_row["finished_at"] = now
        if error_code is not None:
            op_row["error_code"] = error_code
        if error_message is not None:
            op_row["error_message"] = error_message
        return True

    if not _update_op_status(op, "running"):
        op["error_code"] = "INVALID_TRANSITION"
        op["error_message"] = "illegal operation status transition"
        op["status"] = "failed"
        op["finished_at"] = now
        _save("k8s_operations.json", ops)
        return _err("INVALID_TRANSITION", "illegal operation status transition", error_code="INVALID_TRANSITION", operation=op)

    payload = {
        "action": "scale",
        "resource_type": rtype_norm,
        "namespace": ns,
        "name": rname,
        "context": ctx_name,
        "replicas": replicas,
        "message": f"Scaled {rtype_norm}/{rname} in namespace {ns} to replicas={replicas}."
    }
    res_id = _new_id("res")
    resp_bytes = len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    res = {
        "id": res_id,
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": payload,
        "truncated": False,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res)
    _save("k8s_operation_results.json", results)

    _update_op_status(op, "succeeded")
    op["response_size_bytes"] = max(0, int(resp_bytes))
    _save("k8s_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "result": res, "meta": {"latency_ms": latency_ms}}

def k8s_autoscale_resource(context, namespace, resource_type, name, min_replicas, max_replicas, cpu_percent=80, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_autoscale_resource"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 512 * 1024

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _choose_api_key_and_authorize(context_row, requested_ns, is_mutation):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")

        ctx_id = context_row.get("id")
        for k in candidates:
            if is_mutation and not bool(k.get("allow_mutations")):
                continue
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None:
                if not isinstance(allowed_ns, list) or requested_ns not in allowed_ns:
                    continue
            return k, None

        # pick most specific error
        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            if is_mutation and not bool(k.get("allow_mutations")):
                return None, _err("UNAUTHORIZED", "Mutations disabled for available API keys", error_code="MUTATIONS_DISABLED")
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None and (not isinstance(allowed_ns, list) or requested_ns not in allowed_ns):
                return None, _err("UNAUTHORIZED", "Namespace is not allowed for available API keys", error_code="FORBIDDEN_NAMESPACE")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        # Prefer active; if not, return best reason
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        # if disabled/error
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        if not isinstance(key_id, str) or not key_id:
            return None, _err("UNAUTHORIZED", "Invalid API key record", error_code="UNAUTHORIZED")

        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10

        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                projected = 1
                if projected > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                projected = cnt + 1
                if projected > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = projected
                found["updated_at"] = now
                updated = True

        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, requested_ns, rtype, rname, group=None, version=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": requested_ns,
            "resource_type": rtype,
            "resource_name": rname,
            "group": group,
            "version": version,
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        op = None
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                op = r
                break
        if op is None:
            return None, _err("NOT_FOUND", "Operation not found to update", error_code="NOT_FOUND", id=op_id)

        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return None, _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION", from_status=cur, to_status=new_status)

        if new_status == "running":
            op["started_at"] = op.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, content_type, payload_json=None, payload_text=None, retention_expires_at=None, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        # exactly_one_of
        if (payload_json is None and payload_text is None) or (payload_json is not None and payload_text is not None):
            return None, _err("VALIDATION_ERROR", "Result must have exactly one of payload_json or payload_text", error_code="VALIDATION_ERROR")
        res_id = _new_id("kres")
        res = {
            "id": res_id,
            "operation_id": operation_id,
            "content_type": content_type,
            "payload_text": payload_text,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": retention_expires_at,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res, None

    _cleanup_expired_results()

    # Validate inputs
    if not isinstance(namespace, str) or not namespace.strip():
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string", error_code="VALIDATION_ERROR", field="namespace")
    if not isinstance(resource_type, str) or not resource_type.strip():
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string", error_code="VALIDATION_ERROR", field="resource_type")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", error_code="VALIDATION_ERROR", field="name")
    if not isinstance(min_replicas, int) or min_replicas < 1 or min_replicas > 10000:
        return _err("VALIDATION_ERROR", "min_replicas must be between 1 and 10000", error_code="VALIDATION_ERROR", error_detail="INVALID_MIN_REPLICAS")
    if not isinstance(max_replicas, int) or max_replicas < 1 or max_replicas > 10000:
        return _err("VALIDATION_ERROR", "max_replicas must be between 1 and 10000", error_code="VALIDATION_ERROR", error_detail="INVALID_MAX_REPLICAS")
    if max_replicas < min_replicas:
        return _err("VALIDATION_ERROR", "max_replicas must be >= min_replicas", error_code="VALIDATION_ERROR", error_detail="INVALID_REPLICA_RANGE")
    if cpu_percent is None:
        cpu_percent = 80
    if not isinstance(cpu_percent, int) or cpu_percent < 1 or cpu_percent > 100:
        return _err("VALIDATION_ERROR", "cpu_percent must be between 1 and 100", error_code="VALIDATION_ERROR", error_detail="INVALID_CPU_PERCENT")

    supported = {"deployment", "statefulset", "replicaset"}
    rt_norm = resource_type.strip().lower()
    if rt_norm not in supported:
        return _err("VALIDATION_ERROR", "Unsupported resource_type for autoscale", error_code="VALIDATION_ERROR", supported=sorted(list(supported)))

    # Resolve context
    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err

    # Choose API key and enforce allowlists/mutations
    api_key, auth_err = _choose_api_key_and_authorize(ctx, namespace, True)
    if auth_err:
        return auth_err

    # Rate limit
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    params = {
        "context": context,
        "namespace": namespace,
        "resource_type": resource_type,
        "name": name,
        "min_replicas": min_replicas,
        "max_replicas": max_replicas,
        "cpu_percent": cpu_percent
    }

    # Record operation (queued)
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, namespace, resource_type, name, group="autoscaling", version="v2")

    # Transition to running
    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    # Produce a realistic HPA object payload
    hpa = {
        "apiVersion": "autoscaling/v2",
        "kind": "HorizontalPodAutoscaler",
        "metadata": {"name": f"{name}-hpa", "namespace": namespace},
        "spec": {
            "scaleTargetRef": {"apiVersion": "apps/v1", "kind": rt_norm.capitalize() if rt_norm != "replicaset" else "ReplicaSet", "name": name},
            "minReplicas": min_replicas,
            "maxReplicas": max_replicas,
            "metrics": [{
                "type": "Resource",
                "resource": {"name": "cpu", "target": {"type": "Utilization", "averageUtilization": cpu_percent}}
            }]
        }
    }
    resp_obj = {"applied": True, "hpa": hpa}
    resp_size = _json_size(resp_obj)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        # truncate by dropping expanded object
        truncated = True
        resp_obj = {"applied": True, "hpa": {"apiVersion": hpa["apiVersion"], "kind": hpa["kind"], "metadata": hpa["metadata"]}, "notice": "payload truncated"}

    res, res_err = _store_result(op["id"], "application/json", payload_json=resp_obj, retention_expires_at=None, truncated=truncated)
    if res_err:
        opf, _ = _transition_operation(op["id"], "failed", error_code=res_err["error"].get("error_code") or res_err["error"]["code"], error_message=res_err["error"]["message"], response_size_bytes=0)
        return res_err

    # Succeed operation
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(resp_obj))
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation": opf,
        "result": res,
        "latency_ms": latency_ms
    }

def k8s_update_resources(context, namespace, resource_type, name, container, memory_request=None, memory_limit=None, cpu_request=None, cpu_limit=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_nonempty_str(v):
        return isinstance(v, str) and v.strip() != ""

    def _resolve_context(context_name, contexts):
        for c in contexts:
            if c.get("context_name") == context_name:
                return c
        return None

    def _pick_api_key(keys):
        active = [k for k in keys if k.get("status") == "active"]
        if not active:
            return None
        for k in active:
            if k.get("allow_mutations") is True:
                return k
        return active[0]

    def _record_op(ops, api_key_id, context_id, tool_name, is_mutation, requested_namespace, resource_type_v, resource_name_v, parameters):
        op_id = _new_id("op")
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": tool_name,
            "status": "queued",
            "is_mutation": bool(is_mutation),
            "requested_namespace": requested_namespace,
            "resource_type": resource_type_v,
            "resource_name": resource_name_v,
            "group": None,
            "version": None,
            "parameters": parameters,
            "request_size_bytes": _json_size(parameters),
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        return op

    def _set_status(op, new_status):
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        op["status"] = new_status
        op["updated_at"] = now
        if new_status == "running":
            op["started_at"] = now
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now
            op["finished_at"] = now
        return True

    def _rate_limit_check_and_increment(counters, api_key_row):
        key_id = api_key_row["id"]
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            return False, "VALIDATION_ERROR", "Invalid api key rate_limit_rpm"
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            return False, "VALIDATION_ERROR", "Invalid api key burst_limit"

        def bucket_start(window_seconds):
            dt = datetime.datetime.utcnow().replace(microsecond=0)
            epoch = int(dt.timestamp())
            start_epoch = epoch - (epoch % window_seconds)
            return datetime.datetime.utcfromtimestamp(start_epoch).replace(microsecond=0).isoformat() + "Z"

        def get_bucket(window_seconds):
            ws = window_seconds
            wstart = bucket_start(ws)
            for b in counters:
                if b.get("api_key_id") == key_id and b.get("context_id") is None and b.get("window_seconds") == ws and b.get("window_start_at") == wstart:
                    return b
            b = {
                "id": _new_id("rl"),
                "api_key_id": key_id,
                "context_id": None,
                "window_start_at": wstart,
                "window_seconds": ws,
                "count": 0,
                "created_at": now,
                "updated_at": now
            }
            counters.append(b)
            return b

        b60 = get_bucket(60)
        b1 = get_bucket(1)

        projected_60 = int(b60.get("count", 0)) + 1
        projected_1 = int(b1.get("count", 0)) + 1

        if projected_60 > rpm or projected_1 > burst:
            return False, "RATE_LIMIT", "Rate limit exceeded"

        b60["count"] = projected_60
        b60["updated_at"] = now
        b1["count"] = projected_1
        b1["updated_at"] = now
        return True, None, None

    # Basic validations
    if not _is_nonempty_str(context):
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not _is_nonempty_str(namespace):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string", error_code="VALIDATION_ERROR")
    if not _is_nonempty_str(resource_type):
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string", error_code="VALIDATION_ERROR")
    if not _is_nonempty_str(name):
        return _err("VALIDATION_ERROR", "name must be a non-empty string", error_code="VALIDATION_ERROR")
    if not _is_nonempty_str(container):
        return _err("VALIDATION_ERROR", "container must be a non-empty string", error_code="VALIDATION_ERROR")

    supported = {"deployment", "statefulset", "daemonset"}
    rt = resource_type.strip().lower()
    if rt not in supported:
        return _err("VALIDATION_ERROR", "Unsupported resource_type for update_resources", error_code="VALIDATION_ERROR", supported=list(sorted(supported)))

    # Validate resource quantity strings superficially (k8s allows many forms; accept common patterns)
    qty_re = re.compile(r"^[0-9]+(?:\.[0-9]+)?(?:m|Ki|Mi|Gi|Ti|Pi|Ei|K|M|G|T|P|E)?$")
    cpu_re = re.compile(r"^[0-9]+(?:m|(?:\.[0-9]+)?)$")  # simplistic
    def _valid_qty(v, kind):
        if v is None:
            return True
        if not isinstance(v, str) or v.strip() == "":
            return False
        s = v.strip()
        if kind == "cpu":
            return bool(cpu_re.match(s)) or bool(qty_re.match(s))
        return bool(qty_re.match(s))

    if not _valid_qty(memory_request, "mem"):
        return _err("VALIDATION_ERROR", "memory_request is not a valid quantity string", error_code="VALIDATION_ERROR")
    if not _valid_qty(memory_limit, "mem"):
        return _err("VALIDATION_ERROR", "memory_limit is not a valid quantity string", error_code="VALIDATION_ERROR")
    if not _valid_qty(cpu_request, "cpu"):
        return _err("VALIDATION_ERROR", "cpu_request is not a valid quantity string", error_code="VALIDATION_ERROR")
    if not _valid_qty(cpu_limit, "cpu"):
        return _err("VALIDATION_ERROR", "cpu_limit is not a valid quantity string", error_code="VALIDATION_ERROR")

    contexts = _load("k8s_contexts.json")
    keys = _load("api_keys.json")
    ops = _load("k8s_operations.json")
    results = _load("k8s_operation_results.json")
    counters = _load("rate_limit_counters.json")

    ctx = _resolve_context(context, contexts)
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("CONFLICT", "Context is not active", error_code="CONTEXT_DISABLED")

    api_key = _pick_api_key(keys)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")

    allow_ctx = api_key.get("allowed_context_ids", None)
    if allow_ctx is not None:
        if not isinstance(allow_ctx, list) or ctx.get("id") not in allow_ctx:
            return _err("UNAUTHORIZED", "API key not permitted for this context", error_code="FORBIDDEN_CONTEXT")

    allow_ns = api_key.get("allowed_namespaces", None)
    if allow_ns is not None:
        if not isinstance(allow_ns, list) or namespace not in allow_ns:
            return _err("UNAUTHORIZED", "API key not permitted for this namespace", error_code="FORBIDDEN_NAMESPACE")

    if api_key.get("allow_mutations") is not True:
        return _err("UNAUTHORIZED", "Mutations are disabled for this API key", error_code="MUTATIONS_DISABLED")

    ok, ecode, emsg = _rate_limit_check_and_increment(counters, api_key)
    if not ok:
        _save("rate_limit_counters.json", counters)
        return _err(ecode, emsg, error_code="RATE_LIMITED")

    params = {
        "context": context,
        "namespace": namespace,
        "resource_type": resource_type,
        "name": name,
        "container": container,
        "memory_request": memory_request,
        "memory_limit": memory_limit,
        "cpu_request": cpu_request,
        "cpu_limit": cpu_limit
    }

    op = _record_op(
        ops, api_key["id"], ctx["id"], "k8s_update_resources", True, namespace, rt, name, params
    )

    if not _set_status(op, "running"):
        op["error_code"] = "INVALID_TRANSITION"
        op["error_message"] = "Illegal status transition"
        _set_status(op, "failed")
        _save("k8s_operations.json", ops)
        _save("rate_limit_counters.json", counters)
        return _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION")

    # Offline success with intended patch representation
    patch = {
        "kind": rt,
        "namespace": namespace,
        "name": name,
        "container": container,
        "resources": {
            "requests": {k: v for k, v in (("cpu", cpu_request), ("memory", memory_request)) if v is not None},
            "limits": {k: v for k, v in (("cpu", cpu_limit), ("memory", memory_limit)) if v is not None},
        },
        "note": "Result reflects intended resource update; offline mode does not mutate a live cluster."
    }

    res_row = {
        "id": _new_id("res"),
        "operation_id": op["id"],
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": patch,
        "truncated": False,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res_row)

    op["response_size_bytes"] = _json_size(patch)
    if not _set_status(op, "succeeded"):
        op["error_code"] = "INVALID_TRANSITION"
        op["error_message"] = "Illegal status transition"
        _set_status(op, "failed")

    _save("k8s_operations.json", ops)
    _save("k8s_operation_results.json", results)
    _save("rate_limit_counters.json", counters)

    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "result": res_row, "meta": {"latency_ms": latency_ms}}

def k8s_diagnose_application(context, namespace, app_name, resource_type="deployment", **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_diagnose_application"
    IS_MUTATION = False
    RETENTION_SECONDS = 3600
    MAX_RESULT_BYTES = 512 * 1024

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _choose_api_key_and_authorize(context_row, requested_ns):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")
        ctx_id = context_row.get("id")
        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None:
                if not isinstance(allowed_ns, list) or requested_ns not in allowed_ns:
                    continue
            return k, None

        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None and (not isinstance(allowed_ns, list) or requested_ns not in allowed_ns):
                return None, _err("UNAUTHORIZED", "Namespace is not allowed for available API keys", error_code="FORBIDDEN_NAMESPACE")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10

        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if isinstance(r, dict) and r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                if 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                if cnt + 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = cnt + 1
                found["updated_at"] = now
                updated = True
        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, requested_ns, rtype, rname):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": False,
            "requested_namespace": requested_ns,
            "resource_type": rtype,
            "resource_name": rname,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
