        "recommendations": [
            "Verify workload exists and is healthy: kubectl get/describe for the workload and its pods.",
            "Check recent events in the namespace for scheduling/image-pull/probe failures.",
            "Inspect logs for failing pods/containers."
        ],
        "notes": {"mode": "offline_datastore_simulation"}
    }
    resp_size = _json_size(report)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        report = {"summary": report["summary"], "notes": report["notes"], "notice": "payload truncated"}

    retention_expires_at = (now_dt + datetime.timedelta(seconds=RETENTION_SECONDS)).isoformat() + "Z"
    res = _store_result(op["id"], report, truncated=truncated, retention_expires_at=retention_expires_at)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(report))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

