            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": False,
            "requested_namespace": None,
            "resource_type": None,
            "resource_name": None,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
