        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, payload_json, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        res = {
            "id": _new_id("kres"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": None,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    def _best_effort_extract_identity(text):
        # Accept that yaml_content may be non-YAML in this offline simulation; do a permissive extraction.
        if not isinstance(text, str):
            return None
        api = re.search(r"(?mi)^\s*apiVersion\s*:\s*([A-Za-z0-9\.\-/]+)\s*$", text)
        kind = re.search(r"(?mi)^\s*kind\s*:\s*([A-Za-z0-9]+)\s*$", text)
        name_m = re.search(r"(?mi)^\s*name\s*:\s*(.+?)\s*$", text)
        ns_m = re.search(r"(?mi)^\s*namespace\s*:\s*(.+?)\s*$", text)
        api_v = api.group(1).strip() if api else None
        kind_v = kind.group(1).strip() if kind else None
        name_v = None
        if name_m:
            name_v = name_m.group(1).strip().strip("'").strip('"')
        ns_v = None
        if ns_m:
            ns_v = ns_m.group(1).strip().strip("'").strip('"')
        return api_v, kind_v, name_v, ns_v

    _cleanup_expired_results()

    if not isinstance(yaml_content, str) or not yaml_content.strip():
        return _err("VALIDATION_ERROR", "yaml_content must be a non-empty string", error_code="VALIDATION_ERROR", field="yaml_content")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string when provided", error_code="VALIDATION_ERROR", field="namespace")

    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err

    # Use provided namespace only for allowlist enforcement; object may be cluster-scoped.
    api_key, auth_err = _choose_api_key_and_authorize(ctx, namespace)
    if auth_err:
        return auth_err
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    api_v, kind_v, name_v, ns_v = _best_effort_extract_identity(yaml_content)

    # Relax validation: accept non-YAML inputs in offline mode, but if identity fields exist, validate presence.
    # Do NOT reject when yaml_content is a datastore identifier or arbitrary text (audit defect).
    rtype = kind_v if kind_v else None
    rname = name_v if name_v else None
    requested_ns = namespace or ns_v

    params = {"context": context, "yaml_content": yaml_content, "namespace": namespace}
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, requested_ns, rtype, rname)

    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    # Result: simulate creation response.
    created = {
        "created": True,
        "notes": {"mode": "offline_datastore_simulation"},
        "object_ref": {
            "apiVersion": api_v,
            "kind": kind_v,
            "name": name_v,
            "namespace": (ns_v or namespace)
        }
    }
    # If apiVersion/kind/name absent, still accept but be explicit.
    if not api_v or not kind_v or not name_v:
        created["object_ref"]["warning"] = "apiVersion/kind/metadata.name not fully detected; accepted as opaque manifest in offline mode."

    resp_size = _json_size(created)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        created = {"created": True, "object_ref": created["object_ref"], "notice": "payload truncated"}

    res = _store_result(op["id"], created, truncated=truncated)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(created))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

def k8s_apply_resource(context, yaml_content, namespace=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_apply_resource"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 512 * 1024

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _choose_api_key_and_authorize(context_row, requested_ns):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")
        ctx_id = context_row.get("id")
        for k in candidates:
            if not bool(k.get("allow_mutations")):
                continue
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None:
                if not isinstance(allowed_ns, list) or requested_ns not in allowed_ns:
                    continue
            return k, None

        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            if not bool(k.get("allow_mutations")):
                return None, _err("UNAUTHORIZED", "Mutations disabled for available API keys", error_code="MUTATIONS_DISABLED")
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None and (not isinstance(allowed_ns, list) or requested_ns not in allowed_ns):
                return None, _err("UNAUTHORIZED", "Namespace is not allowed for available API keys", error_code="FORBIDDEN_NAMESPACE")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10
        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if isinstance(r, dict) and r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                if 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                if cnt + 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = cnt + 1
                found["updated_at"] = now
                updated = True
        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, requested_ns, rtype, rname):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": requested_ns,
            "resource_type": rtype,
            "resource_name": rname,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        op = None
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                op = r
                break
        if op is None:
            return None, _err("NOT_FOUND", "Operation not found to update", error_code="NOT_FOUND", id=op_id)
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return None, _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION", from_status=cur, to_status=new_status)
        if new_status == "running":
            op["started_at"] = op.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, payload_json, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        res = {
            "id": _new_id("kres"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": None,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    def _best_effort_extract_identity(text):
        if not isinstance(text, str):
            return None
        api = re.search(r"(?mi)^\s*apiVersion\s*:\s*([A-Za-z0-9\.\-/]+)\s*$", text)
        kind = re.search(r"(?mi)^\s*kind\s*:\s*([A-Za-z0-9]+)\s*$", text)
        name_m = re.search(r"(?mi)^\s*name\s*:\s*(.+?)\s*$", text)
        ns_m = re.search(r"(?mi)^\s*namespace\s*:\s*(.+?)\s*$", text)
        api_v = api.group(1).strip() if api else None
        kind_v = kind.group(1).strip() if kind else None
        name_v = None
        if name_m:
            name_v = name_m.group(1).strip().strip("'").strip('"')
        ns_v = None
        if ns_m:
            ns_v = ns_m.group(1).strip().strip("'").strip('"')
        return api_v, kind_v, name_v, ns_v

    _cleanup_expired_results()

    if not isinstance(yaml_content, str) or not yaml_content.strip():
        return _err("VALIDATION_ERROR", "yaml_content must be a non-empty string", error_code="VALIDATION_ERROR", field="yaml_content")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string when provided", error_code="VALIDATION_ERROR", field="namespace")

    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err

    api_key, auth_err = _choose_api_key_and_authorize(ctx, namespace)
    if auth_err:
        return auth_err
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    api_v, kind_v, name_v, ns_v = _best_effort_extract_identity(yaml_content)
    rtype = kind_v if kind_v else None
    rname = name_v if name_v else None
    requested_ns = namespace or ns_v

    params = {"context": context, "yaml_content": yaml_content, "namespace": namespace}
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, requested_ns, rtype, rname)

    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    applied = {
        "applied": True,
        "notes": {"mode": "offline_datastore_simulation"},
        "object_ref": {
            "apiVersion": api_v,
            "kind": kind_v,
            "name": name_v,
            "namespace": (ns_v or namespace)
        }
    }
    if not api_v or not kind_v or not name_v:
        applied["object_ref"]["warning"] = "apiVersion/kind/metadata.name not fully detected; accepted as opaque manifest in offline mode."

    resp_size = _json_size(applied)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        applied = {"applied": True, "object_ref": applied["object_ref"], "notice": "payload truncated"}

    res = _store_result(op["id"], applied, truncated=truncated)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(applied))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

def k8s_patch_resource(context, resource_type, name, patch, namespace=None, **_extra):
    import json, os, datetime, re, hashlib, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TOOL = "k8s_patch_resource"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 256 * 1024

    def _estimate_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if not s: return None
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _window_start(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0)

    def _require_str(v, field):
        if not isinstance(v, str) or not v.strip():
            return _err("VALIDATION_ERROR", f"'{field}' must be a non-empty string", field=field)
        return None

    def _is_known_namespaced_kind(kind):
        k = (kind or "").strip().lower()
        namespaced = {
            "pod","pods","deployment","deployments","service","services","ingress","ingresses",
            "configmap","configmaps","secret","secrets","statefulset","statefulsets","daemonset","daemonsets",
            "job","jobs","cronjob","cronjobs","replicaset","replicasets","pvc","persistentvolumeclaim","persistentvolumeclaims",
            "role","roles","rolebinding","rolebindings","serviceaccount","serviceaccounts",
            "horizontalpodautoscaler","horizontalpodautoscalers",
            "networkpolicy","networkpolicies",
            "endpoints","endpoint",
            "lease","leases",
            "poddisruptionbudget","poddisruptionbudgets",
        }
        cluster_scoped = {
            "node","nodes","namespace","namespaces","clusterrole","clusterroles","clusterrolebinding","clusterrolebindings",
            "persistentvolume","persistentvolumes","crd","crds","customresourcedefinition","customresourcedefinitions",
            "storageclass","storageclasses","volumeattachment","volumeattachments",
        }
        if k in cluster_scoped:
            return False
        if k in namespaced:
            return True
        if "/" in k:
            return namespace is not None
        return namespace is not None

    # Validate inputs
    for field, val in (("context", context), ("resource_type", resource_type), ("name", name), ("patch", patch)):
        e = _require_str(val, field)
        if e: return e
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "'namespace' must be a non-empty string when provided", field="namespace")
    if not isinstance(patch, str):
        return _err("VALIDATION_ERROR", "'patch' must be a string", field="patch")

    if _is_known_namespaced_kind(resource_type) and namespace is None:
        return _err("VALIDATION_ERROR", "Namespace is required for this resource type", error_code="NAMESPACE_REQUIRED")

    # Parse patch payload (must be JSON object or array)
    patch_obj = None
    try:
        patch_obj = json.loads(patch)
    except Exception:
        return _err("VALIDATION_ERROR", "Patch payload is malformed (must be valid JSON string)", field="patch")
    if not isinstance(patch_obj, (dict, list)):
        return _err("VALIDATION_ERROR", "Patch payload must be a JSON object or array", field="patch")

    # Resolve active context
    contexts = _load("k8s_contexts.json")
    ctx = None
    for c in contexts:
        if c.get("context_name") == context:
            ctx = c
            break
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    # Resolve an API key that can serve this request (ambient auth)
    keys = _load("api_keys.json")
    eligible = []
    for k in keys:
        if k.get("status") != "active":
            continue
        if not k.get("allow_mutations", False):
            continue
        aci = k.get("allowed_context_ids", None)
        if aci is not None and ctx.get("id") not in aci:
            continue
        ans = k.get("allowed_namespaces", None)
        if ans is not None and namespace is not None and namespace not in ans:
            continue
        eligible.append(k)
    if not eligible:
        # Decide best error
        any_active = [k for k in keys if k.get("status") == "active"]
        if any_active and all(not k.get("allow_mutations", False) for k in any_active):
            return _err("UNAUTHORIZED", "Mutations are disabled for available API keys", error_code="MUTATIONS_DISABLED")
        return _err("UNAUTHORIZED", "No authorized API key available for this request", error_code="UNAUTHORIZED")
    api_key = eligible[0]

    # Rate limiting (1s burst and 60s rpm) BEFORE creating operation
    counters = _load("rate_limit_counters.json")
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        projected = (bucket.get("count", 0) if bucket else 0) + 1
        limit = api_key.get("burst_limit") if win == 1 else api_key.get("rate_limit_rpm")
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "API key rate limits misconfigured", error_code="VALIDATION_ERROR")
        if projected > limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=win, limit=limit)
    # Passed: increment counters
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        if bucket:
            bucket["count"] = int(bucket.get("count", 0)) + 1
            bucket["updated_at"] = now
        else:
            counters.append({
                "id": _gen_id("rlc"),
                "api_key_id": api_key.get("id"),
                "context_id": None,
                "window_start_at": ws_iso,
                "window_seconds": win,
                "count": 1,
                "created_at": now,
                "updated_at": now
            })
    _save("rate_limit_counters.json", counters)

    # Create operation row (queued->running->succeeded)
    ops = _load("k8s_operations.json")
    op_id = _gen_id("op")
    params = {"context": context, "resource_type": resource_type, "name": name, "patch": patch, "namespace": namespace}
    op = {
        "id": op_id,
        "api_key_id": api_key.get("id"),
        "context_id": ctx.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "is_mutation": True,
        "requested_namespace": namespace,
        "resource_type": resource_type,
        "resource_name": name,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": _estimate_size(params),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    # Transition queued->running
    op["status"] = "running"
    op["started_at"] = now
    op["updated_at"] = now
    _save("k8s_operations.json", ops)

    # Perform "cluster call" simulation: store patched resource payload
    results = _load("k8s_operation_results.json")
    resource = {
        "apiVersion": "v1",
        "kind": resource_type,
        "metadata": {
            "name": name,
            "namespace": namespace,
            "managedFields": None
        },
        "patched": True,
        "patch": patch_obj
    }
    payload = {"resource": resource, "status": "Patched"}
    resp_bytes = _estimate_size(payload)
    truncated = False
    if resp_bytes > MAX_RESULT_BYTES:
        truncated = True
        # Keep minimal payload
        payload = {"resource": {"kind": resource_type, "metadata": {"name": name, "namespace": namespace}}, "status": "Patched", "truncated": True}
        resp_bytes = _estimate_size(payload)

    res = {
        "id": _gen_id("res"),
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": payload,
        "truncated": bool(truncated),
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res)
    _save("k8s_operation_results.json", results)

    # Transition running->succeeded
    op["status"] = "succeeded"
    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op["updated_at"] = op["finished_at"]
    op["response_size_bytes"] = resp_bytes
    _save("k8s_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation": op,
        "result": res,
        "meta": {"latency_ms": latency_ms}
    }

def k8s_label_resource(context, resource_type, name, labels, namespace=None, overwrite=False, **_extra):
    import json, os, datetime, re, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TOOL = "k8s_label_resource"
    MAX_RESULT_BYTES = 256 * 1024

    def _estimate_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _window_start(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0)

    def _require_str(v, field):
        if not isinstance(v, str) or not v.strip():
            return _err("VALIDATION_ERROR", f"'{field}' must be a non-empty string", field=field)
        return None

    def _is_known_namespaced_kind(kind):
        k = (kind or "").strip().lower()
        namespaced = {
            "pod","pods","deployment","deployments","service","services","ingress","ingresses",
            "configmap","configmaps","secret","secrets","statefulset","statefulsets","daemonset","daemonsets",
            "job","jobs","cronjob","cronjobs","replicaset","replicasets","pvc","persistentvolumeclaim","persistentvolumeclaims",
            "role","roles","rolebinding","rolebindings","serviceaccount","serviceaccounts",
            "horizontalpodautoscaler","horizontalpodautoscalers",
            "networkpolicy","networkpolicies",
            "endpoints","endpoint",
            "lease","leases",
            "poddisruptionbudget","poddisruptionbudgets",
        }
        cluster_scoped = {
            "node","nodes","namespace","namespaces","clusterrole","clusterroles","clusterrolebinding","clusterrolebindings",
            "persistentvolume","persistentvolumes","crd","crds","customresourcedefinition","customresourcedefinitions",
            "storageclass","storageclasses","volumeattachment","volumeattachments",
        }
        if k in cluster_scoped:
            return False
        if k in namespaced:
            return True
        if "/" in k:
            return namespace is not None
        return namespace is not None

    def _parse_kv_list(s, field):
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"'{field}' must be a non-empty string", field=field), None
        pairs = {}
        # Accept "k=v,k2=v2" or whitespace-separated
        parts = []
        for chunk in s.replace("\n", " ").split(","):
            chunk = chunk.strip()
            if not chunk:
                continue
            parts.extend([p for p in chunk.split() if p.strip()])
        if not parts:
            return _err("VALIDATION_ERROR", f"'{field}' must contain at least one key=value pair", field=field), None
        key_re = re.compile(r"^(?:[A-Za-z0-9]([A-Za-z0-9_.-]{0,61}[A-Za-z0-9])?)(?:/(?:[A-Za-z0-9]([A-Za-z0-9_.-]{0,61}[A-Za-z0-9])?))?$")
        val_re = re.compile(r"^[A-Za-z0-9_.-]{0,63}$")
        for p in parts:
            if "=" not in p:
                return _err("VALIDATION_ERROR", f"Invalid {field} entry '{p}' (expected key=value)", field=field), None
            k, v = p.split("=", 1)
            k = k.strip()
            v = v.strip()
            if not k:
                return _err("VALIDATION_ERROR", f"Invalid {field} key in '{p}'", field=field), None
            if not key_re.match(k):
                return _err("VALIDATION_ERROR", f"Invalid {field} key '{k}'", field=field), None
            if not val_re.match(v):
                return _err("VALIDATION_ERROR", f"Invalid {field} value for key '{k}'", field=field), None
            pairs[k] = v
        return None, pairs

    # Validate inputs
    for field, val in (("context", context), ("resource_type", resource_type), ("name", name), ("labels", labels)):
        e = _require_str(val, field)
        if e: return e
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "'namespace' must be a non-empty string when provided", field="namespace")
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "'overwrite' must be boolean", field="overwrite")

    if _is_known_namespaced_kind(resource_type) and namespace is None:
        return _err("VALIDATION_ERROR", "Namespace is required for this resource type", error_code="NAMESPACE_REQUIRED")

    le, label_map = _parse_kv_list(labels, "labels")
    if le: return le

    # Resolve active context
    contexts = _load("k8s_contexts.json")
    ctx = None
    for c in contexts:
        if c.get("context_name") == context:
            ctx = c
            break
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    # Resolve API key (ambient) with mutation permission
    keys = _load("api_keys.json")
    eligible = []
    for k in keys:
        if k.get("status") != "active":
            continue
        if not k.get("allow_mutations", False):
            continue
        aci = k.get("allowed_context_ids", None)
        if aci is not None and ctx.get("id") not in aci:
            continue
        ans = k.get("allowed_namespaces", None)
        if ans is not None and namespace is not None and namespace not in ans:
            continue
        eligible.append(k)
    if not eligible:
        any_active = [k for k in keys if k.get("status") == "active"]
        if any_active and all(not k.get("allow_mutations", False) for k in any_active):
            return _err("UNAUTHORIZED", "Mutations are disabled for available API keys", error_code="MUTATIONS_DISABLED")
        return _err("UNAUTHORIZED", "No authorized API key available for this request", error_code="UNAUTHORIZED")
    api_key = eligible[0]

    # Rate limiting
    counters = _load("rate_limit_counters.json")
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        projected = (bucket.get("count", 0) if bucket else 0) + 1
        limit = api_key.get("burst_limit") if win == 1 else api_key.get("rate_limit_rpm")
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "API key rate limits misconfigured", error_code="VALIDATION_ERROR")
        if projected > limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=win, limit=limit)
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        if bucket:
            bucket["count"] = int(bucket.get("count", 0)) + 1
            bucket["updated_at"] = now
        else:
            counters.append({
                "id": _gen_id("rlc"),
                "api_key_id": api_key.get("id"),
                "context_id": None,
                "window_start_at": ws_iso,
                "window_seconds": win,
                "count": 1,
                "created_at": now,
                "updated_at": now
            })
    _save("rate_limit_counters.json", counters)

    # Create operation and complete it
    ops = _load("k8s_operations.json")
    op_id = _gen_id("op")
    params = {
        "context": context, "resource_type": resource_type, "name": name,
        "labels": labels, "namespace": namespace, "overwrite": overwrite
    }
    op = {
        "id": op_id,
        "api_key_id": api_key.get("id"),
        "context_id": ctx.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "is_mutation": True,
        "requested_namespace": namespace,
        "resource_type": resource_type,
        "resource_name": name,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": _estimate_size(params),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    op["status"] = "running"
    op["started_at"] = now
    op["updated_at"] = now
    _save("k8s_operations.json", ops)

    updated = {
        "apiVersion": "v1",
        "kind": resource_type,
        "metadata": {
            "name": name,
            "namespace": namespace,
            "labels_applied": label_map,
            "overwrite": overwrite
        },
        "status": "Labeled"
    }
    payload = {"resource": updated}
    resp_bytes = _estimate_size(payload)
    truncated = False
    if resp_bytes > MAX_RESULT_BYTES:
        truncated = True
        payload = {"resource": {"kind": resource_type, "metadata": {"name": name, "namespace": namespace}}, "truncated": True}
        resp_bytes = _estimate_size(payload)

    results = _load("k8s_operation_results.json")
    res = {
        "id": _gen_id("res"),
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": payload,
        "truncated": bool(truncated),
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res)
    _save("k8s_operation_results.json", results)

    op["status"] = "succeeded"
    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op["updated_at"] = op["finished_at"]
    op["response_size_bytes"] = resp_bytes
    _save("k8s_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "result": res, "meta": {"latency_ms": latency_ms}}

def k8s_annotate_resource(context, resource_type, name, annotations, namespace=None, overwrite=False, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_annotate_resource"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 256 * 1024

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _choose_api_key_and_authorize(context_row, requested_ns):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")
        ctx_id = context_row.get("id")
        for k in candidates:
            if not bool(k.get("allow_mutations")):
                continue
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None:
                if not isinstance(allowed_ns, list) or requested_ns not in allowed_ns:
                    continue
            return k, None

        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            if not bool(k.get("allow_mutations")):
                return None, _err("UNAUTHORIZED", "Mutations disabled for available API keys", error_code="MUTATIONS_DISABLED")
            allowed_ns = k.get("allowed_namespaces")
            if requested_ns is not None and allowed_ns is not None and (not isinstance(allowed_ns, list) or requested_ns not in allowed_ns):
                return None, _err("UNAUTHORIZED", "Namespace is not allowed for available API keys", error_code="FORBIDDEN_NAMESPACE")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10
        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if isinstance(r, dict) and r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                if 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                if cnt + 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = cnt + 1
                found["updated_at"] = now
                updated = True
        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, requested_ns, rtype, rname):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": requested_ns,
            "resource_type": rtype,
            "resource_name": rname,
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        op = None
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                op = r
                break
        if op is None:
            return None, _err("NOT_FOUND", "Operation not found to update", error_code="NOT_FOUND", id=op_id)
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return None, _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION", from_status=cur, to_status=new_status)
        if new_status == "running":
            op["started_at"] = op.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, payload_json, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        res = {
            "id": _new_id("kres"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": None,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    _cleanup_expired_results()

    if not isinstance(resource_type, str) or not resource_type.strip():
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string", error_code="VALIDATION_ERROR", field="resource_type")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", error_code="VALIDATION_ERROR", field="name")
    if not isinstance(annotations, str) or not annotations.strip():
        return _err("VALIDATION_ERROR", "annotations must be a non-empty string", error_code="VALIDATION_ERROR", field="annotations")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string when provided", error_code="VALIDATION_ERROR", field="namespace")
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "overwrite must be boolean", error_code="VALIDATION_ERROR", field="overwrite")

    # Parse annotations: accept "k=v,k2=v2" (values may contain '=' minimally)
    pairs = []
    for part in [p.strip() for p in annotations.split(",") if p.strip()]:
        if "=" not in part:
            return _err("VALIDATION_ERROR", "Invalid annotation syntax; expected k=v pairs", error_code="VALIDATION_ERROR", field="annotations")
        k, v = part.split("=", 1)
        k = k.strip()
        v = v.strip()
        if not k or not re.match(r"^[A-Za-z0-9\.\-_/]+$", k):
            return _err("VALIDATION_ERROR", "Invalid annotation key", error_code="VALIDATION_ERROR", field="annotations", key=k)
        pairs.append((k, v))

    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err
    api_key, auth_err = _choose_api_key_and_authorize(ctx, namespace)
    if auth_err:
        return auth_err
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    params = {
        "context": context,
        "resource_type": resource_type,
        "name": name,
        "annotations": annotations,
        "namespace": namespace,
        "overwrite": overwrite
    }
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, namespace, resource_type, name)

    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    updated = {
        "annotated": True,
        "resource": {"kind": resource_type, "name": name, "namespace": namespace},
        "applied_annotations": {k: v for (k, v) in pairs},
        "overwrite": overwrite,
        "notes": {"mode": "offline_datastore_simulation"}
    }
    resp_size = _json_size(updated)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        updated = {"annotated": True, "resource": updated["resource"], "notice": "payload truncated"}

    res = _store_result(op["id"], updated, truncated=truncated)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(updated))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

def k8s_expose_resource(context, resource_type, name, port, target_port=None, namespace=None, protocol=None, service_name=None, labels=None, selector=None, type=None, **_extra):
    import json, os, datetime, re, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TOOL = "k8s_expose_resource"
    MAX_RESULT_BYTES = 256 * 1024

    def _estimate_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _window_start(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0)

    def _require_str(v, field):
        if not isinstance(v, str) or not v.strip():
            return _err("VALIDATION_ERROR", f"'{field}' must be a non-empty string", field=field)
        return None

    def _is_known_namespaced_kind(kind):
        k = (kind or "").strip().lower()
        namespaced = {
            "pod","pods","deployment","deployments","service","services","ingress","ingresses",
            "configmap","configmaps","secret","secrets","statefulset","statefulsets","daemonset","daemonsets",
            "job","jobs","cronjob","cronjobs","replicaset","replicasets","pvc","persistentvolumeclaim","persistentvolumeclaims",
            "role","roles","rolebinding","rolebindings","serviceaccount","serviceaccounts",
            "horizontalpodautoscaler","horizontalpodautoscalers",
            "networkpolicy","networkpolicies",
            "endpoints","endpoint",
            "lease","leases",
            "poddisruptionbudget","poddisruptionbudgets",
        }
        cluster_scoped = {
            "node","nodes","namespace","namespaces","clusterrole","clusterroles","clusterrolebinding","clusterrolebindings",
            "persistentvolume","persistentvolumes","crd","crds","customresourcedefinition","customresourcedefinitions",
            "storageclass","storageclasses","volumeattachment","volumeattachments",
        }
        if k in cluster_scoped:
            return False
        if k in namespaced:
            return True
        if "/" in k:
            return namespace is not None
        return namespace is not None

    def _parse_kv_list_optional(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"'{field}' must be a non-empty string when provided", field=field), None
        pairs = {}
        parts = []
        for chunk in s.replace("\n", " ").split(","):
            chunk = chunk.strip()
            if not chunk:
                continue
            parts.extend([p for p in chunk.split() if p.strip()])
        if not parts:
            return _err("VALIDATION_ERROR", f"'{field}' must contain at least one key=value pair", field=field), None
        key_re = re.compile(r"^(?:[A-Za-z0-9]([A-Za-z0-9_.-]{0,61}[A-Za-z0-9])?)(?:/(?:[A-Za-z0-9]([A-Za-z0-9_.-]{0,61}[A-Za-z0-9])?))?$")
        val_re = re.compile(r"^[A-Za-z0-9_.-]{0,63}$")
        for p in parts:
            if "=" not in p:
                return _err("VALIDATION_ERROR", f"Invalid {field} entry '{p}' (expected key=value)", field=field), None
            k, v = p.split("=", 1)
            k = k.strip()
            v = v.strip()
            if not k or not key_re.match(k):
                return _err("VALIDATION_ERROR", f"Invalid {field} key '{k}'", field=field), None
            if not val_re.match(v):
                return _err("VALIDATION_ERROR", f"Invalid {field} value for key '{k}'", field=field), None
            pairs[k] = v
        return None, pairs

    # Validate inputs
    for field, val in (("context", context), ("resource_type", resource_type), ("name", name)):
        e = _require_str(val, field)
        if e: return e
    if not isinstance(port, int):
        return _err("VALIDATION_ERROR", "'port' must be an integer", field="port")
    if port < 1 or port > 65535:
        return _err("VALIDATION_ERROR", "Port out of range", error_code="INVALID_PORT", field="port")
    if target_port is not None:
        if not isinstance(target_port, int):
            return _err("VALIDATION_ERROR", "'target_port' must be an integer when provided", field="target_port")
        if target_port < 1 or target_port > 65535:
            return _err("VALIDATION_ERROR", "Target port out of range", error_code="INVALID_PORT", field="target_port")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "'namespace' must be a non-empty string when provided", field="namespace")
    if protocol is not None:
        if not isinstance(protocol, str):
            return _err("VALIDATION_ERROR", "'protocol' must be a string when provided", field="protocol")
        if protocol not in ("TCP", "UDP", "SCTP"):
            return _err("VALIDATION_ERROR", "Invalid protocol", field="protocol")
    if service_name is not None and (not isinstance(service_name, str) or not service_name.strip()):
        return _err("VALIDATION_ERROR", "'service_name' must be a non-empty string when provided", field="service_name")
    if type is not None and (not isinstance(type, str) or not type.strip()):
        return _err("VALIDATION_ERROR", "'type' must be a non-empty string when provided", field="type")

    # For exposing workloads, generally namespaced; enforce namespace if kind is known namespaced
    if _is_known_namespaced_kind(resource_type) and namespace is None:
        return _err("VALIDATION_ERROR", "Namespace is required for this resource type", error_code="NAMESPACE_REQUIRED")

    le, label_map = _parse_kv_list_optional(labels, "labels")
    if le: return le
    se, selector_map = _parse_kv_list_optional(selector, "selector")
    if se: return se

    # Resolve active context
    contexts = _load("k8s_contexts.json")
    ctx = None
    for c in contexts:
        if c.get("context_name") == context:
            ctx = c
            break
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    # Resolve API key (ambient) with mutation permission and allowlists
    keys = _load("api_keys.json")
    eligible = []
    for k in keys:
        if k.get("status") != "active":
            continue
        if not k.get("allow_mutations", False):
            continue
        aci = k.get("allowed_context_ids", None)
        if aci is not None and ctx.get("id") not in aci:
            continue
        ans = k.get("allowed_namespaces", None)
        if ans is not None and namespace is not None and namespace not in ans:
            continue
        eligible.append(k)
    if not eligible:
        any_active = [k for k in keys if k.get("status") == "active"]
        if any_active and all(not k.get("allow_mutations", False) for k in any_active):
            return _err("UNAUTHORIZED", "Mutations are disabled for available API keys", error_code="MUTATIONS_DISABLED")
        # Distinguish forbidden namespace/context if possible
        for k in any_active:
            if k.get("allow_mutations", False):
                aci = k.get("allowed_context_ids", None)
                if aci is not None and ctx.get("id") not in aci:
                    return _err("UNAUTHORIZED", "Context not permitted by API key", error_code="FORBIDDEN_CONTEXT")
                ans = k.get("allowed_namespaces", None)
                if ans is not None and namespace is not None and namespace not in ans:
                    return _err("UNAUTHORIZED", "Namespace not permitted by API key", error_code="FORBIDDEN_NAMESPACE")
        return _err("UNAUTHORIZED", "No authorized API key available for this request", error_code="UNAUTHORIZED")
    api_key = eligible[0]

    # Rate limiting
    counters = _load("rate_limit_counters.json")
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        projected = (bucket.get("count", 0) if bucket else 0) + 1
        limit = api_key.get("burst_limit") if win == 1 else api_key.get("rate_limit_rpm")
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "API key rate limits misconfigured", error_code="VALIDATION_ERROR")
        if projected > limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=win, limit=limit)
    for win in (1, 60):
        ws = _window_start(now_dt, win)
        ws_iso = ws.isoformat() + "Z"
        bucket = None
        for b in counters:
            if b.get("api_key_id") == api_key.get("id") and b.get("context_id") is None and b.get("window_seconds") == win and b.get("window_start_at") == ws_iso:
                bucket = b
                break
        if bucket:
            bucket["count"] = int(bucket.get("count", 0)) + 1
            bucket["updated_at"] = now
        else:
            counters.append({
                "id": _gen_id("rlc"),
                "api_key_id": api_key.get("id"),
                "context_id": None,
                "window_start_at": ws_iso,
                "window_seconds": win,
                "count": 1,
                "created_at": now,
                "updated_at": now
            })
    _save("rate_limit_counters.json", counters)

    # Create operation and complete it
    ops = _load("k8s_operations.json")
    op_id = _gen_id("op")
    params = {
        "context": context, "resource_type": resource_type, "name": name, "port": port,
        "target_port": target_port, "namespace": namespace, "protocol": protocol,
        "service_name": service_name, "labels": labels, "selector": selector, "type": type
    }
    op = {
        "id": op_id,
        "api_key_id": api_key.get("id"),
        "context_id": ctx.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "is_mutation": True,
        "requested_namespace": namespace,
        "resource_type": resource_type,
        "resource_name": name,
        "group": None,
        "version": None,
        "parameters": params,
        "request_size_bytes": _estimate_size(params),
        "response_size_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("k8s_operations.json", ops)

    op["status"] = "running"
    op["started_at"] = now
    op["updated_at"] = now
    _save("k8s_operations.json", ops)

    svc_name = service_name.strip() if isinstance(service_name, str) and service_name.strip() else f"{name}-svc"
    svc_type = type.strip() if isinstance(type, str) and type.strip() else "ClusterIP"
    proto = protocol if protocol is not None else "TCP"
    tport = target_port if target_port is not None else port

    service = {
        "apiVersion": "v1",
        "kind": "Service",
        "metadata": {
            "name": svc_name,
            "namespace": namespace,
            "labels": label_map or {}
        },
        "spec": {
            "type": svc_type,
            "ports": [{"port": port, "targetPort": tport, "protocol": proto}],
            "selector": selector_map or {}
        },
        "exposes": {"kind": resource_type, "name": name, "namespace": namespace}
    }
    payload = {"service": service}
    resp_bytes = _estimate_size(payload)
    truncated = False
    if resp_bytes > MAX_RESULT_BYTES:
        truncated = True
        payload = {"service": {"metadata": {"name": svc_name, "namespace": namespace}, "spec": {"type": svc_type}}, "truncated": True}
        resp_bytes = _estimate_size(payload)

    results = _load("k8s_operation_results.json")
    res = {
        "id": _gen_id("res"),
        "operation_id": op_id,
        "content_type": "application/json",
        "payload_text": None,
        "payload_json": payload,
        "truncated": bool(truncated),
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    results.append(res)
    _save("k8s_operation_results.json", results)

    op["status"] = "succeeded"
    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op["updated_at"] = op["finished_at"]
    op["response_size_bytes"] = resp_bytes
    _save("k8s_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "result": res, "meta": {"latency_ms": latency_ms}}

def k8s_cordon_node(context, node_name, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_cordon_node"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 256 * 1024

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _choose_api_key_and_authorize(context_row):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")
        ctx_id = context_row.get("id")
        for k in candidates:
            if not bool(k.get("allow_mutations")):
                continue
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            return k, None

        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            if not bool(k.get("allow_mutations")):
                return None, _err("UNAUTHORIZED", "Mutations disabled for available API keys", error_code="MUTATIONS_DISABLED")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10
        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if isinstance(r, dict) and r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                if 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                if cnt + 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = cnt + 1
                found["updated_at"] = now
                updated = True
        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, rname):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": None,
            "resource_type": "Node",
            "resource_name": rname,
            "group": None,
            "version": "v1",
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        op = None
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                op = r
                break
        if op is None:
            return None, _err("NOT_FOUND", "Operation not found to update", error_code="NOT_FOUND", id=op_id)
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return None, _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION", from_status=cur, to_status=new_status)
        if new_status == "running":
            op["started_at"] = op.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, payload_json, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        res = {
            "id": _new_id("kres"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": None,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    _cleanup_expired_results()

    if not isinstance(node_name, str) or not node_name.strip():
        return _err("VALIDATION_ERROR", "node_name must be a non-empty string", error_code="VALIDATION_ERROR", field="node_name")
    if not re.match(r"^[A-Za-z0-9\.\-]+$", node_name.strip()):
        return _err("VALIDATION_ERROR", "node_name has invalid characters", error_code="VALIDATION_ERROR", field="node_name")

    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err
    api_key, auth_err = _choose_api_key_and_authorize(ctx)
    if auth_err:
        return auth_err
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    params = {"context": context, "node_name": node_name}
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, node_name)
    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    payload = {
        "cordoned": True,
        "node": {"name": node_name, "unschedulable": True},
        "notes": {"mode": "offline_datastore_simulation"}
    }
    resp_size = _json_size(payload)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        payload = {"cordoned": True, "node": {"name": node_name}, "notice": "payload truncated"}

    res = _store_result(op["id"], payload, truncated=truncated)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(payload))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

def k8s_uncordon_node(context, node_name, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_str(s):
        if s is None or not isinstance(s, str):
            return None
        s2 = s.strip()
        return s2 if s2 else None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _cleanup_expired_results(results, operations):
        now = datetime.datetime.utcnow()
        ops_by_id = {o.get("id") for o in operations if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_by_id:
                changed = True
                continue
            exp = r.get("retention_expires_at")
            if exp:
                try:
                    s = exp[:-1] if isinstance(exp, str) and exp.endswith("Z") else exp
                    dt = datetime.datetime.fromisoformat(s)
                    if dt <= now:
                        changed = True
                        continue
                except Exception:
                    pass
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)
        return kept

    def _select_api_key_for_call(is_mutation):
        keys = _load("api_keys.json")
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if is_mutation and not k.get("allow_mutations", False):
                continue
            try:
                rpm = int(k.get("rate_limit_rpm"))
                burst = int(k.get("burst_limit"))
            except Exception:
                continue
            if rpm < 1 or rpm > 60000 or burst < 1 or burst > 10000:
                continue
            return k
        return None

    def _resolve_context(context_name):
        for c in _load("k8s_contexts.json"):
            if isinstance(c, dict) and c.get("context_name") == context_name:
                return c
        return None

    def _check_acl(api_key_row, context_row):
        allow_ctx = api_key_row.get("allowed_context_ids")
        if allow_ctx is not None:
            if not isinstance(allow_ctx, list) or context_row.get("id") not in allow_ctx:
                return _err("UNAUTHORIZED", "API key not permitted for this context.", error_code="FORBIDDEN_CONTEXT")
        return None

    def _rate_limit(api_key_row):
        counters = _load("rate_limit_counters.json")
        now = datetime.datetime.utcnow()
        now_iso = _now()

        def bucket_start(window_seconds):
            epoch = int(now.timestamp())
            start = epoch - (epoch % window_seconds)
            return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

        def find_or_create(window_seconds):
            ws = int(window_seconds)
            wstart = bucket_start(ws)
            for row in counters:
                if not isinstance(row, dict):
                    continue
                if row.get("api_key_id") == api_key_row.get("id") and row.get("context_id") is None and row.get("window_seconds") == ws and row.get("window_start_at") == wstart:
                    return row
            row = {
                "id": _gen_id("rlc"),
                "api_key_id": api_key_row.get("id"),
                "context_id": None,
                "window_start_at": wstart,
                "window_seconds": ws,
                "count": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            counters.append(row)
            return row

        b60 = find_or_create(60)
        b1 = find_or_create(1)

        try:
            rpm = int(api_key_row.get("rate_limit_rpm"))
            burst = int(api_key_row.get("burst_limit"))
        except Exception:
            return _err("UNAUTHORIZED", "API key has invalid rate limit configuration.", error_code="RATE_LIMITED")

        if int(b60.get("count", 0)) + 1 > rpm or int(b1.get("count", 0)) + 1 > burst:
            _save("rate_limit_counters.json", counters)
            return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMITED")

        b60["count"] = int(b60.get("count", 0)) + 1
        b1["count"] = int(b1.get("count", 0)) + 1
        b60["updated_at"] = now_iso
        b1["updated_at"] = now_iso
        _save("rate_limit_counters.json", counters)
        return None

    def _create_operation(api_key_id, context_id, params, status, started_at=None, finished_at=None, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        now_iso = _now()
        op = {
            "id": _gen_id("op"),
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": "k8s_uncordon_node",
            "status": status,
            "is_mutation": True,
            "requested_namespace": None,
            "resource_type": "Node",
            "resource_name": params.get("node_name"),
            "group": None,
            "version": None,
            "parameters": params,
            "request_size_bytes": max(0, _json_size_bytes(params)),
            "response_size_bytes": response_size_bytes,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _update_operation_status(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        now_iso = _now()
        op = None
        for row in ops:
            if isinstance(row, dict) and row.get("id") == op_id:
                op = row
                break
        if op is None:
            return None
        allowed = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = op.get("status")
        if cur not in allowed or new_status not in allowed[cur]:
            return "INVALID_TRANSITION"
        op["status"] = new_status
        op["updated_at"] = now_iso
        if new_status == "running":
            op["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now_iso
            op["finished_at"] = now_iso
        if error_code is not None:
            op["error_code"] = error_code
        if error_message is not None:
            op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = max(0, int(response_size_bytes))
        _save("k8s_operations.json", ops)
        return op

    def _store_result(operation_id, payload):
        results = _load("k8s_operation_results.json")
        operations = _load("k8s_operations.json")
        results = _cleanup_expired_results(results, operations)
        now_iso = _now()
        row = {
            "id": _gen_id("res"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload,
            "truncated": False,
            "retention_expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        results.append(row)
        _save("k8s_operation_results.json", results)
        return row

    t0 = time.time()

    ctx_name = _norm_str(context)
    if not ctx_name:
        return _err("VALIDATION_ERROR", "context must be a non-empty string.", error_code="INVALID_CONTEXT")
    nname = _norm_str(node_name)
    if not nname:
        return _err("VALIDATION_ERROR", "node_name must be a non-empty string.", error_code="INVALID_NODE_NAME")

    api_key = _select_api_key_for_call(is_mutation=True)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key is able to perform this operation.", error_code="UNAUTHORIZED")

    ctx = _resolve_context(ctx_name)
    params = {"context": context, "node_name": node_name}
    if ctx is None:
        op = _create_operation(api_key.get("id"), "", params, status="failed", started_at=_now(), finished_at=_now(), error_code="CONTEXT_NOT_FOUND", error_message="Context not registered.", response_size_bytes=0)
        return _err("NOT_FOUND", "Context not found.", error_code="CONTEXT_NOT_FOUND", operation_id=op.get("id"))
    if ctx.get("status") != "active":
        op = _create_operation(api_key.get("id"), ctx.get("id"), params, status="failed", started_at=_now(), finished_at=_now(), error_code="CONTEXT_DISABLED", error_message="Context is not active.", response_size_bytes=0)
        return _err("CONFLICT", "Context is disabled or in error state.", error_code="CONTEXT_DISABLED", operation_id=op.get("id"), context_status=ctx.get("status"))

    acl_err = _check_acl(api_key, ctx)
    if acl_err is not None:
        op = _create_operation(api_key.get("id"), ctx.get("id"), params, status="failed", started_at=_now(), finished_at=_now(), error_code=acl_err["error"].get("error_code"), error_message=acl_err["error"]["message"], response_size_bytes=0)
        acl_err["error"]["operation_id"] = op.get("id")
        return acl_err

    if not api_key.get("allow_mutations", False):
        op = _create_operation(api_key.get("id"), ctx.get("id"), params, status="failed", started_at=_now(), finished_at=_now(), error_code="MUTATIONS_DISABLED", error_message="Mutations disabled for this API key.", response_size_bytes=0)
        return _err("UNAUTHORIZED", "Mutations are disabled for this API key.", error_code="MUTATIONS_DISABLED", operation_id=op.get("id"))

    rl_err = _rate_limit(api_key)
    if rl_err is not None:
        op = _create_operation(api_key.get("id"), ctx.get("id"), params, status="failed", started_at=_now(), finished_at=_now(), error_code="RATE_LIMITED", error_message="Rate limit exceeded.", response_size_bytes=0)
        rl_err["error"]["operation_id"] = op.get("id")
        return rl_err

    op = _create_operation(api_key.get("id"), ctx.get("id"), params, status="queued")
    if _update_operation_status(op.get("id"), "running") == "INVALID_TRANSITION":
        return _err("INVALID_TRANSITION", "Operation status transition is invalid.", error_code="INVALID_TRANSITION", operation_id=op.get("id"))

    payload = {
        "action": "uncordon",
        "context": ctx.get("context_name"),
        "node_name": nname,
        "unschedulable": False,
        "note": "Offline datastore-backed server: node update not executed; request recorded.",
    }
    res = _store_result(op.get("id"), payload)
    resp_size = _json_size_bytes(payload)
    _update_operation_status(op.get("id"), "succeeded", response_size_bytes=resp_size)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation": {"id": op.get("id"), "status": "succeeded", "latency_ms": latency_ms},
        "result": {"id": res.get("id"), "content_type": "application/json", "truncated": False, "payload": payload},
    }

def k8s_drain_node(context, node_name, force=None, ignore_daemonsets=None, delete_local_data=None, timeout=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    TOOL = "k8s_drain_node"
    IS_MUTATION = True
    MAX_RESULT_BYTES = 256 * 1024

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _window_start_iso(dt, seconds):
        epoch = int(dt.timestamp())
        start = epoch - (epoch % seconds)
        return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0).isoformat() + "Z"

    def _cleanup_expired_results():
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        ops_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        kept = []
        changed = False
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in ops_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp is not None and exp <= now_dt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _resolve_context(context_name):
        if not isinstance(context_name, str) or not context_name.strip():
            return None, _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR", field="context")
        contexts = _load("k8s_contexts.json")
        if not isinstance(contexts, list):
            contexts = []
        matches = [c for c in contexts if isinstance(c, dict) and c.get("context_name") == context_name]
        if not matches:
            return None, _err("NOT_FOUND", "Context not registered", error_code="CONTEXT_NOT_FOUND", context=context_name)
        active = [c for c in matches if c.get("status") == "active"]
        if active:
            return active[0], None
        st = matches[0].get("status")
        if st == "disabled":
            return None, _err("UNAUTHORIZED", "Context is disabled", error_code="CONTEXT_DISABLED", context=context_name)
        return None, _err("NOT_FOUND", "Context is not active", error_code="CONTEXT_NOT_FOUND", context=context_name, status=st)

    def _choose_api_key_and_authorize(context_row):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available", error_code="UNAUTHORIZED")
        ctx_id = context_row.get("id")
        for k in candidates:
            if not bool(k.get("allow_mutations")):
                continue
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None:
                if not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx:
                    continue
            return k, None

        for k in candidates:
            allowed_ctx = k.get("allowed_context_ids")
            if allowed_ctx is not None and (not isinstance(allowed_ctx, list) or ctx_id not in allowed_ctx):
                continue
            if not bool(k.get("allow_mutations")):
                return None, _err("UNAUTHORIZED", "Mutations disabled for available API keys", error_code="MUTATIONS_DISABLED")
        return None, _err("UNAUTHORIZED", "Context is not allowed for available API keys", error_code="FORBIDDEN_CONTEXT")

    def _rate_limit_and_record_counter(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        key_id = api_key_row.get("id")
        rpm = api_key_row.get("rate_limit_rpm")
        burst = api_key_row.get("burst_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
            rpm = 60
        if not isinstance(burst, int) or burst < 1 or burst > 10000:
            burst = 10
        updated = False
        for window_seconds, limit in ((60, rpm), (1, burst)):
            ws = _window_start_iso(now_dt, window_seconds)
            found = None
            for r in counters:
                if isinstance(r, dict) and r.get("api_key_id") == key_id and r.get("context_id") == context_id and r.get("window_seconds") == window_seconds and r.get("window_start_at") == ws:
                    found = r
                    break
            if found is None:
                if 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                counters.append({
                    "id": _new_id("rlc"),
                    "api_key_id": key_id,
                    "context_id": context_id,
                    "window_start_at": ws,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now,
                    "updated_at": now
                })
                updated = True
            else:
                cnt = found.get("count")
                if not isinstance(cnt, int) or cnt < 0:
                    cnt = 0
                if cnt + 1 > limit:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", window_seconds=window_seconds, limit=limit)
                found["count"] = cnt + 1
                found["updated_at"] = now
                updated = True
        if updated:
            _save("rate_limit_counters.json", counters)
        return True, None

    def _record_operation(api_key_id, context_id, params, rname):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        op_id = _new_id("kop")
        req_sz = _json_size(params)
        op = {
            "id": op_id,
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": TOOL,
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": None,
            "resource_type": "Node",
            "resource_name": rname,
            "group": None,
            "version": "v1",
            "parameters": params,
            "request_size_bytes": int(req_sz) if isinstance(req_sz, int) and req_sz >= 0 else 0,
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _transition_operation(op_id, new_status, error_code=None, error_message=None, response_size_bytes=None):
        ops = _load("k8s_operations.json")
        if not isinstance(ops, list):
            ops = []
        transitions = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        op = None
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                op = r
                break
        if op is None:
            return None, _err("NOT_FOUND", "Operation not found to update", error_code="NOT_FOUND", id=op_id)
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return None, _err("INVALID_TRANSITION", "Illegal operation status transition", error_code="INVALID_TRANSITION", from_status=cur, to_status=new_status)
        if new_status == "running":
            op["started_at"] = op.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled"):
            op["started_at"] = op.get("started_at") or now
            op["finished_at"] = now
        op["status"] = new_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_size_bytes is not None:
            op["response_size_bytes"] = int(response_size_bytes) if isinstance(response_size_bytes, int) and response_size_bytes >= 0 else 0
        op["updated_at"] = now
        _save("k8s_operations.json", ops)
        return op, None

    def _store_result(operation_id, payload_json, truncated=False):
        results = _load("k8s_operation_results.json")
        if not isinstance(results, list):
            results = []
        res = {
            "id": _new_id("kres"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": None,
            "created_at": now,
            "updated_at": now
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    _cleanup_expired_results()

    if not isinstance(node_name, str) or not node_name.strip():
        return _err("VALIDATION_ERROR", "node_name must be a non-empty string", error_code="VALIDATION_ERROR", field="node_name")
    if not re.match(r"^[A-Za-z0-9\.\-]+$", node_name.strip()):
        return _err("VALIDATION_ERROR", "node_name has invalid characters", error_code="VALIDATION_ERROR", field="node_name")
    for bname, bval in (("force", force), ("ignore_daemonsets", ignore_daemonsets), ("delete_local_data", delete_local_data)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be boolean when provided", error_code="VALIDATION_ERROR", field=bname)
    if timeout is not None:
        if not isinstance(timeout, int) or timeout < 1 or timeout > 3600:
            return _err("VALIDATION_ERROR", "timeout must be an integer between 1 and 3600 seconds when provided", error_code="VALIDATION_ERROR", field="timeout")

    ctx, ctx_err = _resolve_context(context)
    if ctx_err:
        return ctx_err
    api_key, auth_err = _choose_api_key_and_authorize(ctx)
    if auth_err:
        return auth_err
    ok, rl_err = _rate_limit_and_record_counter(api_key, ctx.get("id"))
    if rl_err:
        return rl_err

    params = {
        "context": context,
        "node_name": node_name,
        "force": bool(force) if force is not None else False,
        "ignore_daemonsets": bool(ignore_daemonsets) if ignore_daemonsets is not None else False,
        "delete_local_data": bool(delete_local_data) if delete_local_data is not None else False,
        "timeout": timeout
    }
    op = _record_operation(api_key.get("id"), ctx.get("id"), params, node_name)
    op2, tr_err = _transition_operation(op["id"], "running")
    if tr_err:
        return tr_err

    payload = {
        "drained": True,
        "node": {"name": node_name},
        "options": {
            "force": params["force"],
            "ignore_daemonsets": params["ignore_daemonsets"],
            "delete_local_data": params["delete_local_data"],
            "timeout": timeout
        },
        "notes": {"mode": "offline_datastore_simulation"}
    }
    resp_size = _json_size(payload)
    truncated = False
    if isinstance(resp_size, int) and resp_size > MAX_RESULT_BYTES:
        truncated = True
        payload = {"drained": True, "node": {"name": node_name}, "notice": "payload truncated"}

    res = _store_result(op["id"], payload, truncated=truncated)
    opf, _ = _transition_operation(op["id"], "succeeded", response_size_bytes=_json_size(payload))
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": opf, "result": res, "latency_ms": latency_ms}

def k8s_taint_node(context, node_name, key, value=None, effect=None, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _bg_delete_expired_results():
        # Background-style cleanup: delete expired results and cascade-delete orphan results.
        ops = _load("k8s_operations.json")
        results = _load("k8s_operation_results.json")
        nowdt = datetime.datetime.utcnow()
        op_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        changed = False
        kept = []
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            rid = r.get("id")
            oid = r.get("operation_id")
            if oid not in op_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp and exp <= nowdt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _find_usable_api_key(is_mutation):
        keys = _load("api_keys.json")
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if is_mutation and not bool(k.get("allow_mutations", False)):
                continue
            # basic constraint sanity
            try:
                rpm = int(k.get("rate_limit_rpm"))
                burst = int(k.get("burst_limit"))
            except Exception:
                continue
            if rpm < 1 or rpm > 60000 or burst < 1 or burst > 10000:
                continue
            return k
        return None

    def _resolve_context_by_name(name):
        ctxs = _load("k8s_contexts.json")
        for c in ctxs:
            if not isinstance(c, dict):
                continue
            if c.get("context_name") == name:
                return c
        return None

    def _rate_limit_check_and_increment(api_key_row, context_id):
        counters = _load("rate_limit_counters.json")
        nowdt = datetime.datetime.utcnow()
        now_iso = nowdt.replace(microsecond=0).isoformat() + "Z"

        def window_start(seconds):
            epoch = int(nowdt.timestamp())
            start = epoch - (epoch % seconds)
            return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0)

        def upsert(window_seconds, limit):
            nonlocal counters
            ws = window_start(window_seconds)
            ws_iso = ws.isoformat() + "Z"
            # global per-key bucket (context_id null)
            idx = None
            for i, row in enumerate(counters):
                if not isinstance(row, dict):
                    continue
                if row.get("api_key_id") == api_key_row["id"] and row.get("context_id") is None and row.get("window_seconds") == window_seconds and row.get("window_start_at") == ws_iso:
                    idx = i
                    break
            current = 0
            if idx is not None:
                try:
                    current = int(counters[idx].get("count", 0))
                except Exception:
                    current = 0
            projected = current + 1
            if projected > limit:
                return False, projected, limit, ws_iso
            if idx is None:
                counters.append({
                    "id": _gen_id("rlc"),
                    "api_key_id": api_key_row["id"],
                    "context_id": None,
                    "window_start_at": ws_iso,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now_iso,
                    "updated_at": now_iso
                })
            else:
                counters[idx]["count"] = projected
                counters[idx]["updated_at"] = now_iso
            return True, projected, limit, ws_iso

        ok1, p1, l1, ws1 = upsert(60, int(api_key_row["rate_limit_rpm"]))
        if not ok1:
            return False, {"window_seconds": 60, "window_start_at": ws1, "limit": l1, "count": p1}
        ok2, p2, l2, ws2 = upsert(1, int(api_key_row["burst_limit"]))
        if not ok2:
            return False, {"window_seconds": 1, "window_start_at": ws2, "limit": l2, "count": p2}

        _save("rate_limit_counters.json", counters)
        return True, None

    def _create_operation(api_key_id, context_id, tool_name, is_mutation, requested_namespace, resource_type, resource_name, group, version, parameters):
        ops = _load("k8s_operations.json")
        now_iso = _now()
        op = {
            "id": _gen_id("op"),
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": tool_name,
            "status": "queued",
            "is_mutation": bool(is_mutation),
            "requested_namespace": requested_namespace,
            "resource_type": resource_type,
            "resource_name": resource_name,
            "group": group,
            "version": version,
            "parameters": parameters if isinstance(parameters, dict) else {},
            "request_size_bytes": _json_size(parameters),
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _op_transition(op_id, new_status, error_code=None, error_message=None, response_obj=None):
        ops = _load("k8s_operations.json")
        op = None
        idx = None
        for i, o in enumerate(ops):
            if isinstance(o, dict) and o.get("id") == op_id:
                op = o
                idx = i
                break
        if op is None:
            return None

        transitions = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            # refuse illegal transition
            op["error_code"] = "INVALID_TRANSITION"
            op["error_message"] = f"Illegal transition {cur}->{new_status}"
            op["updated_at"] = _now()
            ops[idx] = op
            _save("k8s_operations.json", ops)
            return op

        now_iso = _now()
        if new_status == "running":
            op["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now_iso
            op["finished_at"] = now_iso

        op["status"] = new_status
        op["updated_at"] = now_iso
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_obj is not None:
            op["response_size_bytes"] = _json_size(response_obj)
        ops[idx] = op
        _save("k8s_operations.json", ops)
        return op

    def _store_result(operation_id, content_type, payload_text, payload_json, truncated, retention_expires_at):
        results = _load("k8s_operation_results.json")
        now_iso = _now()
        # exactly_one_of(payload_text, payload_json)
        if (payload_text is None) == (payload_json is None):
            return None
        res = {
            "id": _gen_id("res"),
            "operation_id": operation_id,
            "content_type": content_type,
            "payload_text": payload_text,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": retention_expires_at,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    # -------- validate inputs
    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(node_name, str) or not node_name.strip():
        return _err("VALIDATION_ERROR", "node_name must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(key, str) or not key.strip():
        return _err("VALIDATION_ERROR", "key must be a non-empty string", error_code="VALIDATION_ERROR")
    if value is not None and not isinstance(value, str):
        return _err("VALIDATION_ERROR", "value must be a string or null", error_code="VALIDATION_ERROR")
    if effect is None:
        effect = "NoSchedule"
    if not isinstance(effect, str):
        return _err("VALIDATION_ERROR", "effect must be a string", error_code="VALIDATION_ERROR")
    if effect not in ("NoSchedule", "PreferNoSchedule", "NoExecute"):
        return _err("VALIDATION_ERROR", "effect is invalid", error_code="VALIDATION_ERROR")

    # cleanup expired results each call
    try:
        _bg_delete_expired_results()
    except Exception:
        return _err("CONFLICT", "Failed during retention cleanup")

    # resolve an ambient usable API key for mutation tools
    api_key = _find_usable_api_key(is_mutation=True)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key is authorized to perform mutations", error_code="MUTATIONS_DISABLED")

    # resolve context by context_name, require active
    ctx = _resolve_context_by_name(context)
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    # allowlist context
    allow_ctx = api_key.get("allowed_context_ids")
    if allow_ctx is not None:
        if not isinstance(allow_ctx, list) or ctx.get("id") not in allow_ctx:
            return _err("UNAUTHORIZED", "API key is not permitted for this context", error_code="FORBIDDEN_CONTEXT")

    # rate limit before creating/running operation
    ok_rl, rl_meta = _rate_limit_check_and_increment(api_key, ctx.get("id"))
    if not ok_rl:
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", **rl_meta)

    # create operation row (audited)
    params = {"context": context, "node_name": node_name, "key": key, "value": value, "effect": effect}
    op = _create_operation(
        api_key_id=api_key["id"],
        context_id=ctx["id"],
        tool_name="k8s_taint_node",
        is_mutation=True,
        requested_namespace=None,
        resource_type="Node",
        resource_name=node_name,
        group=None,
        version=None,
        parameters=params
    )

    # transition to running
    _op_transition(op["id"], "running")

    # emulate "real" cluster mutation via local persisted node-state inside context record (no separate schema).
    # We'll store node taints under k8s_contexts[].parameters-like field "node_state" (created if missing).
    ctxs = _load("k8s_contexts.json")
    cidx = None
    for i, c in enumerate(ctxs):
        if isinstance(c, dict) and c.get("id") == ctx["id"]:
            cidx = i
            ctx = c
            break
    if cidx is None:
        _op_transition(op["id"], "failed", error_code="CONTEXT_NOT_FOUND", error_message="Context disappeared")
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")

    # node existence: treat nodes list as managed in ctx["node_state"]["nodes"]
    node_state = ctx.get("node_state")
    if node_state is None:
        node_state = {}
    if not isinstance(node_state, dict):
        node_state = {}

    nodes = node_state.get("nodes")
    if nodes is None:
        nodes = []
    if not isinstance(nodes, list):
        nodes = []

    node = None
    nidx = None
    for i, n in enumerate(nodes):
        if isinstance(n, dict) and n.get("name") == node_name:
            node = n
            nidx = i
            break
    if node is None:
        _op_transition(op["id"], "failed", error_code="NODE_NOT_FOUND", error_message="Node not found")
        return _err("NOT_FOUND", "Node not found", error_code="NODE_NOT_FOUND")

    taints = node.get("taints")
    if taints is None:
        taints = []
    if not isinstance(taints, list):
        taints = []

    # add/update by key+effect (common kubectl behavior)
    updated = False
    for t in taints:
        if not isinstance(t, dict):
            continue
        if t.get("key") == key and t.get("effect") == effect:
            t["value"] = value
            t["updated_at"] = _now()
            updated = True
            break
    if not updated:
        taints.append({
            "key": key,
            "value": value,
            "effect": effect,
            "created_at": _now(),
            "updated_at": _now()
        })

    node["taints"] = taints
    nodes[nidx] = node
    node_state["nodes"] = nodes
    ctx["node_state"] = node_state
    ctx["updated_at"] = _now()
    ctxs[cidx] = ctx
    _save("k8s_contexts.json", ctxs)

    response = {"node_name": node_name, "taints": taints}

    # store result (json) - node ops not flagged sensitive by rule, no retention required
    _store_result(op["id"], "application/json", None, response, False, None)

    _op_transition(op["id"], "succeeded", response_obj=response)

    return {"operation": op, "result": response}

