        if new_status == "running":
            op["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now_iso
            op["finished_at"] = now_iso
        op["status"] = new_status
        op["updated_at"] = now_iso
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_obj is not None:
            op["response_size_bytes"] = _json_size(response_obj)
        ops[idx] = op
        _save("k8s_operations.json", ops)
        return op

    def _store_result(operation_id, payload_json):
        results = _load("k8s_operation_results.json")
        now_iso = _now()
        res = {
            "id": _gen_id("res"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": False,
            "retention_expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    # validate
    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(node_name, str) or not node_name.strip():
        return _err("VALIDATION_ERROR", "node_name must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(key, str) or not key.strip():
        return _err("VALIDATION_ERROR", "key must be a non-empty string", error_code="VALIDATION_ERROR")
    if effect is not None:
        if not isinstance(effect, str):
            return _err("VALIDATION_ERROR", "effect must be a string or null", error_code="VALIDATION_ERROR")
        if effect not in ("NoSchedule", "PreferNoSchedule", "NoExecute"):
            return _err("VALIDATION_ERROR", "effect is invalid", error_code="VALIDATION_ERROR")

    try:
        _bg_delete_expired_results()
    except Exception:
        return _err("CONFLICT", "Failed during retention cleanup")

    api_key = _find_usable_api_key(is_mutation=True)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key is authorized to perform mutations", error_code="MUTATIONS_DISABLED")

    ctx = _resolve_context_by_name(context)
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    allow_ctx = api_key.get("allowed_context_ids")
    if allow_ctx is not None:
        if not isinstance(allow_ctx, list) or ctx.get("id") not in allow_ctx:
            return _err("UNAUTHORIZED", "API key is not permitted for this context", error_code="FORBIDDEN_CONTEXT")

    ok_rl, rl_meta = _rate_limit_check_and_increment(api_key)
    if not ok_rl:
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", **(rl_meta or {}))

    params = {"context": context, "node_name": node_name, "key": key, "effect": effect}
    op = _create_operation(api_key["id"], ctx["id"], params)
    _op_transition(op["id"], "running")

    ctxs = _load("k8s_contexts.json")
    cidx = None
    for i, c in enumerate(ctxs):
        if isinstance(c, dict) and c.get("id") == ctx["id"]:
            cidx = i
            ctx = c
            break
    if cidx is None:
        _op_transition(op["id"], "failed", error_code="CONTEXT_NOT_FOUND", error_message="Context disappeared")
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")

    node_state = ctx.get("node_state")
    if node_state is None or not isinstance(node_state, dict):
        node_state = {}
    nodes = node_state.get("nodes")
    if nodes is None or not isinstance(nodes, list):
        nodes = []

    node = None
    nidx = None
    for i, n in enumerate(nodes):
        if isinstance(n, dict) and n.get("name") == node_name:
            node = n
            nidx = i
            break
    if node is None:
        _op_transition(op["id"], "failed", error_code="NODE_NOT_FOUND", error_message="Node not found")
        return _err("NOT_FOUND", "Node not found", error_code="NODE_NOT_FOUND")

    taints = node.get("taints")
    if taints is None or not isinstance(taints, list):
        taints = []

    before = len([t for t in taints if isinstance(t, dict)])
    if effect is None:
        taints2 = [t for t in taints if not (isinstance(t, dict) and t.get("key") == key)]
    else:
        taints2 = [t for t in taints if not (isinstance(t, dict) and t.get("key") == key and t.get("effect") == effect)]
    after = len([t for t in taints2 if isinstance(t, dict)])

    if before == after:
        _op_transition(op["id"], "failed", error_code="TAINT_NOT_FOUND", error_message="No matching taint to remove")
        return _err("NOT_FOUND", "No matching taint found", error_code="TAINT_NOT_FOUND")

    node["taints"] = taints2
    nodes[nidx] = node
    node_state["nodes"] = nodes
    ctx["node_state"] = node_state
    ctx["updated_at"] = _now()
    ctxs[cidx] = ctx
    _save("k8s_contexts.json", ctxs)

    response = {"node_name": node_name, "taints": taints2}
    _store_result(op["id"], response)
    _op_transition(op["id"], "succeeded", response_obj=response)
    return {"operation": op, "result": response}

def k8s_pod_exec(context, pod_name, command, container=None, namespace=None, stdin=None, tty=None, timeout=None, **_extra):
    import json, os, datetime, uuid, subprocess, shlex

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _json_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _bg_delete_expired_results():
        ops = _load("k8s_operations.json")
        results = _load("k8s_operation_results.json")
        nowdt = datetime.datetime.utcnow()
        op_ids = {o.get("id") for o in ops if isinstance(o, dict)}
        changed = False
        kept = []
        for r in results:
            if not isinstance(r, dict):
                changed = True
                continue
            if r.get("operation_id") not in op_ids:
                changed = True
                continue
            exp = _parse_dt(r.get("retention_expires_at"))
            if exp and exp <= nowdt:
                changed = True
                continue
            kept.append(r)
        if changed:
            _save("k8s_operation_results.json", kept)

    def _find_usable_api_key(is_mutation):
        keys = _load("api_keys.json")
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if is_mutation and not bool(k.get("allow_mutations", False)):
                continue
            try:
                rpm = int(k.get("rate_limit_rpm"))
                burst = int(k.get("burst_limit"))
            except Exception:
                continue
            if rpm < 1 or rpm > 60000 or burst < 1 or burst > 10000:
                continue
            return k
        return None

    def _resolve_context_by_name(name):
        ctxs = _load("k8s_contexts.json")
        for c in ctxs:
            if not isinstance(c, dict):
                continue
            if c.get("context_name") == name:
                return c
        return None

    def _rate_limit_check_and_increment(api_key_row):
        counters = _load("rate_limit_counters.json")
        nowdt = datetime.datetime.utcnow()
        now_iso = nowdt.replace(microsecond=0).isoformat() + "Z"

        def window_start(seconds):
            epoch = int(nowdt.timestamp())
            start = epoch - (epoch % seconds)
            return datetime.datetime.utcfromtimestamp(start).replace(microsecond=0)

        def upsert(window_seconds, limit):
            nonlocal counters
            ws = window_start(window_seconds)
            ws_iso = ws.isoformat() + "Z"
            idx = None
            for i, row in enumerate(counters):
                if not isinstance(row, dict):
                    continue
                if row.get("api_key_id") == api_key_row["id"] and row.get("context_id") is None and row.get("window_seconds") == window_seconds and row.get("window_start_at") == ws_iso:
                    idx = i
                    break
            current = 0
            if idx is not None:
                try:
                    current = int(counters[idx].get("count", 0))
                except Exception:
                    current = 0
            projected = current + 1
            if projected > limit:
                return False, {"window_seconds": window_seconds, "window_start_at": ws_iso, "limit": limit, "count": projected}
            if idx is None:
                counters.append({
                    "id": _gen_id("rlc"),
                    "api_key_id": api_key_row["id"],
                    "context_id": None,
                    "window_start_at": ws_iso,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now_iso,
                    "updated_at": now_iso
                })
            else:
                counters[idx]["count"] = projected
                counters[idx]["updated_at"] = now_iso
            return True, None

        ok60, meta60 = upsert(60, int(api_key_row["rate_limit_rpm"]))
        if not ok60:
            return False, meta60
        ok1, meta1 = upsert(1, int(api_key_row["burst_limit"]))
        if not ok1:
            return False, meta1

        _save("rate_limit_counters.json", counters)
        return True, None

    def _create_operation(api_key_id, context_id, requested_namespace, resource_name, parameters):
        ops = _load("k8s_operations.json")
        now_iso = _now()
        op = {
            "id": _gen_id("op"),
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": "k8s_pod_exec",
            "status": "queued",
            "is_mutation": True,
            "requested_namespace": requested_namespace,
            "resource_type": "Pod",
            "resource_name": resource_name,
            "group": None,
            "version": None,
            "parameters": parameters if isinstance(parameters, dict) else {},
            "request_size_bytes": _json_size(parameters),
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _op_transition(op_id, new_status, error_code=None, error_message=None, response_obj=None):
        ops = _load("k8s_operations.json")
        op = None
        idx = None
        for i, o in enumerate(ops):
            if isinstance(o, dict) and o.get("id") == op_id:
                op = o
                idx = i
                break
        if op is None:
            return None
        transitions = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            op["error_code"] = "INVALID_TRANSITION"
            op["error_message"] = f"Illegal transition {cur}->{new_status}"
            op["updated_at"] = _now()
            ops[idx] = op
            _save("k8s_operations.json", ops)
            return op

        now_iso = _now()
        if new_status == "running":
            op["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now_iso
            op["finished_at"] = now_iso
        op["status"] = new_status
        op["updated_at"] = now_iso
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_obj is not None:
            op["response_size_bytes"] = _json_size(response_obj)
        ops[idx] = op
        _save("k8s_operations.json", ops)
        return op

    def _store_result(operation_id, payload_json, truncated, retention_expires_at):
        results = _load("k8s_operation_results.json")
        now_iso = _now()
        res = {
            "id": _gen_id("res"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": bool(truncated),
            "retention_expires_at": retention_expires_at,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    # -------- validate inputs
    if not isinstance(context, str) or not context.strip():
        return _err("VALIDATION_ERROR", "context must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(pod_name, str) or not pod_name.strip():
        return _err("VALIDATION_ERROR", "pod_name must be a non-empty string", error_code="VALIDATION_ERROR")
    if not isinstance(command, str) or not command.strip():
        return _err("VALIDATION_ERROR", "command must be a non-empty string", error_code="VALIDATION_ERROR")
    if container is not None and not isinstance(container, str):
        return _err("VALIDATION_ERROR", "container must be a string or null", error_code="VALIDATION_ERROR")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string or null", error_code="VALIDATION_ERROR")
    if stdin is None:
        stdin = False
    if tty is None:
        tty = False
    if not isinstance(stdin, bool) or not isinstance(tty, bool):
        return _err("VALIDATION_ERROR", "stdin and tty must be booleans", error_code="VALIDATION_ERROR")
    if tty and not stdin:
        return _err("VALIDATION_ERROR", "tty=true requires stdin=true", error_code="VALIDATION_ERROR")
    if timeout is not None:
        if not isinstance(timeout, int):
            return _err("VALIDATION_ERROR", "timeout must be an integer or null", error_code="VALIDATION_ERROR")
        if timeout <= 0:
            return _err("VALIDATION_ERROR", "timeout must be > 0", error_code="VALIDATION_ERROR")

    # enforce timeout ceiling <= 300s even if null
    exec_timeout = 30 if timeout is None else timeout
    if exec_timeout > 300:
        exec_timeout = 300

    try:
        _bg_delete_expired_results()
    except Exception:
        return _err("CONFLICT", "Failed during retention cleanup")

    api_key = _find_usable_api_key(is_mutation=True)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key is authorized to exec into pods", error_code="MUTATIONS_DISABLED")

    ctx = _resolve_context_by_name(context)
    if not ctx:
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")
    if ctx.get("status") != "active":
        return _err("UNAUTHORIZED", "Context is not active", error_code="CONTEXT_DISABLED")

    # context allowlist
    allow_ctx = api_key.get("allowed_context_ids")
    if allow_ctx is not None:
        if not isinstance(allow_ctx, list) or ctx.get("id") not in allow_ctx:
            return _err("UNAUTHORIZED", "API key is not permitted for this context", error_code="FORBIDDEN_CONTEXT")

    # namespace allowlist
    allow_ns = api_key.get("allowed_namespaces")
    if allow_ns is not None and namespace is not None:
        if not isinstance(allow_ns, list) or namespace not in allow_ns:
            return _err("UNAUTHORIZED", "API key is not permitted for this namespace", error_code="FORBIDDEN_NAMESPACE")

    ok_rl, rl_meta = _rate_limit_check_and_increment(api_key)
    if not ok_rl:
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", **(rl_meta or {}))

    params = {
        "context": context,
        "pod_name": pod_name,
        "command": command,
        "container": container,
        "namespace": namespace,
        "stdin": stdin,
        "tty": tty,
        "timeout": timeout
    }
    op = _create_operation(api_key["id"], ctx["id"], namespace, pod_name, params)
    _op_transition(op["id"], "running")

    # validate pod exists (local emulation): stored under ctx["pod_state"]["pods"]
    ctxs = _load("k8s_contexts.json")
    cidx = None
    for i, c in enumerate(ctxs):
        if isinstance(c, dict) and c.get("id") == ctx["id"]:
            cidx = i
            ctx = c
            break
    if cidx is None:
        _op_transition(op["id"], "failed", error_code="CONTEXT_NOT_FOUND", error_message="Context disappeared")
        return _err("NOT_FOUND", "Context not found", error_code="CONTEXT_NOT_FOUND")

    pod_state = ctx.get("pod_state")
    if pod_state is None or not isinstance(pod_state, dict):
        pod_state = {}
    pods = pod_state.get("pods")
    if pods is None or not isinstance(pods, list):
        pods = []

    target_ns = namespace if namespace is not None else (ctx.get("default_namespace") or "default")
    pod = None
    for p in pods:
        if not isinstance(p, dict):
            continue
        if p.get("name") == pod_name and (p.get("namespace") or "default") == target_ns:
            pod = p
            break
    if pod is None:
        _op_transition(op["id"], "failed", error_code="POD_NOT_FOUND", error_message="Pod not found")
        return _err("NOT_FOUND", "Pod not found", error_code="POD_NOT_FOUND")

    # container resolution
    containers = pod.get("containers")
    if containers is None or not isinstance(containers, list) or len(containers) == 0:
        containers = ["primary"]
    if container is None:
        container_used = containers[0]
    else:
        if container not in containers:
            _op_transition(op["id"], "failed", error_code="CONTAINER_NOT_FOUND", error_message="Container not found in pod")
            return _err("NOT_FOUND", "Container not found", error_code="CONTAINER_NOT_FOUND")
        container_used = container

    # Execute locally (offline): run command in a shell-like parsing, capture output.
    # Security note: this is a local emulator; still, avoid shell=True. Use shlex split.
    try:
        argv = shlex.split(command)
        if not argv:
            _op_transition(op["id"], "failed", error_code="VALIDATION_ERROR", error_message="Empty command")
            return _err("VALIDATION_ERROR", "command must not be empty", error_code="VALIDATION_ERROR")
        proc = subprocess.run(
            argv,
            input=None,
            capture_output=True,
            text=True,
            timeout=exec_timeout
        )
        out = proc.stdout or ""
        err = proc.stderr or ""
        exit_code = proc.returncode
        timed_out = False
    except subprocess.TimeoutExpired as te:
        out = (te.stdout or "")
        err = (te.stderr or "")
        exit_code = None
        timed_out = True
    except FileNotFoundError:
        _op_transition(op["id"], "failed", error_code="EXEC_NOT_FOUND", error_message="Executable not found")
        return _err("NOT_FOUND", "Executable not found for command", error_code="EXEC_NOT_FOUND")
    except Exception:
        _op_transition(op["id"], "failed", error_code="EXEC_ERROR", error_message="Failed to execute command")
        return _err("CONFLICT", "Failed to execute command", error_code="EXEC_ERROR")

    # Size cap & truncation for exec output as sensitive
    max_bytes = 64 * 1024
    combined = (out + err)
    b = combined.encode("utf-8", errors="replace")
    truncated = False
    if len(b) > max_bytes:
        truncated = True
        b = b[:max_bytes]
        combined = b.decode("utf-8", errors="replace")

    payload = {
        "context": context,
        "namespace": target_ns,
        "pod_name": pod_name,
        "container": container_used,
        "command": command,
        "timeout_seconds": exec_timeout,
        "timed_out": timed_out,
        "exit_code": exit_code,
        "output": combined
    }

    # retention for exec output (short)
    retention_expires_at = (datetime.datetime.utcnow() + datetime.timedelta(minutes=15)).replace(microsecond=0).isoformat() + "Z"
    _store_result(op["id"], payload, truncated, retention_expires_at)

    if timed_out:
        _op_transition(op["id"], "failed", error_code="TIMEOUT", error_message="Exec timed out", response_obj=payload)
        return _err("CONFLICT", "Exec timed out", error_code="TIMEOUT", operation=op, result=payload)

    _op_transition(op["id"], "succeeded", response_obj=payload)
    return {"operation": op, "result": payload}

