                if not isinstance(row, dict):
                    continue
                if row.get("api_key_id") == api_key_row["id"] and row.get("context_id") is None and row.get("window_seconds") == window_seconds and row.get("window_start_at") == ws_iso:
                    idx = i
                    break
            current = 0
            if idx is not None:
                try:
                    current = int(counters[idx].get("count", 0))
                except Exception:
                    current = 0
            projected = current + 1
            if projected > limit:
                return False, {"window_seconds": window_seconds, "window_start_at": ws_iso, "limit": limit, "count": projected}
            if idx is None:
                counters.append({
                    "id": _gen_id("rlc"),
                    "api_key_id": api_key_row["id"],
                    "context_id": None,
                    "window_start_at": ws_iso,
                    "window_seconds": window_seconds,
                    "count": 1,
                    "created_at": now_iso,
                    "updated_at": now_iso
                })
            else:
                counters[idx]["count"] = projected
                counters[idx]["updated_at"] = now_iso
            return True, None

        ok60, meta60 = upsert(60, int(api_key_row["rate_limit_rpm"]))
        if not ok60:
            return False, meta60
        ok1, meta1 = upsert(1, int(api_key_row["burst_limit"]))
        if not ok1:
            return False, meta1

        _save("rate_limit_counters.json", counters)
        return True, None

    def _create_operation(api_key_id, context_id, parameters):
        ops = _load("k8s_operations.json")
        now_iso = _now()
        op = {
            "id": _gen_id("op"),
            "api_key_id": api_key_id,
            "context_id": context_id,
            "tool_name": "k8s_get_contexts",  # closest audited tool name in enum for context registry reads
            "status": "queued",
            "is_mutation": False,
            "requested_namespace": None,
            "resource_type": "Context",
            "resource_name": id,
            "group": None,
            "version": None,
            "parameters": parameters if isinstance(parameters, dict) else {},
            "request_size_bytes": _json_size(parameters),
            "response_size_bytes": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        ops.append(op)
        _save("k8s_operations.json", ops)
        return op

    def _op_transition(op_id, new_status, error_code=None, error_message=None, response_obj=None):
        ops = _load("k8s_operations.json")
        op = None
        idx = None
        for i, o in enumerate(ops):
            if isinstance(o, dict) and o.get("id") == op_id:
                op = o
                idx = i
                break
        if op is None:
            return None
        transitions = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = op.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            op["error_code"] = "INVALID_TRANSITION"
            op["error_message"] = f"Illegal transition {cur}->{new_status}"
            op["updated_at"] = _now()
            ops[idx] = op
            _save("k8s_operations.json", ops)
            return op

        now_iso = _now()
        if new_status == "running":
            op["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            if not op.get("started_at"):
                op["started_at"] = now_iso
            op["finished_at"] = now_iso
        op["status"] = new_status
        op["updated_at"] = now_iso
        op["error_code"] = error_code
        op["error_message"] = error_message
        if response_obj is not None:
            op["response_size_bytes"] = _json_size(response_obj)
        ops[idx] = op
        _save("k8s_operations.json", ops)
        return op

    def _store_result(operation_id, payload_json):
        results = _load("k8s_operation_results.json")
        now_iso = _now()
        res = {
            "id": _gen_id("res"),
            "operation_id": operation_id,
            "content_type": "application/json",
            "payload_text": None,
            "payload_json": payload_json,
            "truncated": False,
            "retention_expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        results.append(res)
        _save("k8s_operation_results.json", results)
        return res

    # validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", error_code="VALIDATION_ERROR")

    try:
        _bg_delete_expired_results()
    except Exception:
        return _err("CONFLICT", "Failed during retention cleanup")

    api_key = _find_usable_api_key_for_read()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available to service request", error_code="UNAUTHORIZED")

    ok_rl, rl_meta = _rate_limit_check_and_increment(api_key)
    if not ok_rl:
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED", **(rl_meta or {}))

    # read context
    ctxs = _load("k8s_contexts.json")
    ctx = None
    for c in ctxs:
        if isinstance(c, dict) and c.get("id") == id:
            ctx = c
            break
    # Create audited operation even when NOT_FOUND (every invocation must create k8s_operations row)
    op = _create_operation(api_key["id"], id if ctx else (ctxs[0]["id"] if ctxs and isinstance(ctxs[0], dict) and ctxs[0].get("id") else api_key["id"]), {"id": id})
    _op_transition(op["id"], "running")

    if ctx is None:
        _op_transition(op["id"], "failed", error_code="NOT_FOUND", error_message="Context not found")
        return _err("NOT_FOUND", "Context not found", error_code="NOT_FOUND", operation=op)

    # enforce allowlist for viewing metadata (FORBIDDEN if not permitted)
    allow_ctx = api_key.get("allowed_context_ids")
    if allow_ctx is not None:
        if not isinstance(allow_ctx, list) or ctx.get("id") not in allow_ctx:
            _op_transition(op["id"], "failed", error_code="FORBIDDEN_CONTEXT", error_message="Not permitted to view this context")
            return _err("UNAUTHORIZED", "Not permitted to view this context", error_code="FORBIDDEN_CONTEXT", operation=op)

    # Return recorded configuration/status fields (do not fabricate)
    payload = ctx
    _store_result(op["id"], payload)
    _op_transition(op["id"], "succeeded", response_obj=payload)
    return {"operation": op, "context": payload}

def k8s_create_context(context_name, cluster_name, user_name, server, kubeconfig_sources, default_namespace=None, status=None, **_extra):
    import json, os, datetime, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate
    if not isinstance(context_name, str) or not context_name.strip():
        return _err("VALIDATION_ERROR", "context_name must be a non-empty string", error_code="VALIDATION_ERROR", field="context_name")
    if not isinstance(cluster_name, str) or not cluster_name.strip():
        return _err("VALIDATION_ERROR", "cluster_name must be a non-empty string", error_code="VALIDATION_ERROR", field="cluster_name")
    if not isinstance(user_name, str) or not user_name.strip():
        return _err("VALIDATION_ERROR", "user_name must be a non-empty string", error_code="VALIDATION_ERROR", field="user_name")
    if not isinstance(server, str) or not server.strip():
        return _err("VALIDATION_ERROR", "server must be a non-empty string", error_code="VALIDATION_ERROR", field="server")
    if not (server.strip().startswith("http://") or server.strip().startswith("https://")):
        return _err("VALIDATION_ERROR", "server must start with http:// or https://", error_code="VALIDATION_ERROR", field="server")
    if not isinstance(kubeconfig_sources, list) or not kubeconfig_sources:
        return _err("VALIDATION_ERROR", "kubeconfig_sources must be a non-empty array", error_code="VALIDATION_ERROR", field="kubeconfig_sources")
    allowed_sources = {"file", "env", "secret", "inline"}
    for s in kubeconfig_sources:
        if not isinstance(s, str) or s not in allowed_sources:
            return _err("VALIDATION_ERROR", "kubeconfig_sources contains unsupported value", error_code="VALIDATION_ERROR", supported=sorted(list(allowed_sources)))
    if default_namespace is not None:
        if not isinstance(default_namespace, str) or not default_namespace.strip():
            return _err("VALIDATION_ERROR", "default_namespace must be a non-empty string when provided", error_code="VALIDATION_ERROR", field="default_namespace")
        if not re.match(r"^[a-z0-9]([a-z0-9\-\.]*[a-z0-9])?$", default_namespace.strip()):
            return _err("VALIDATION_ERROR", "default_namespace has invalid format", error_code="VALIDATION_ERROR", field="default_namespace")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error", error_code="VALIDATION_ERROR", field="status")

    contexts = _load("k8s_contexts.json")
    if not isinstance(contexts, list):
        contexts = []

    # Uniqueness
    if any(isinstance(c, dict) and c.get("context_name") == context_name.strip() for c in contexts):
        return _err("CONFLICT", "context_name is already registered", error_code="CONFLICT", field="context_name", context_name=context_name.strip())

    ctx_id = f"kctx_{uuid.uuid4().hex}"
    row = {
        "id": ctx_id,
        "context_name": context_name.strip(),
        "cluster_name": cluster_name.strip(),
        "user_name": user_name.strip(),
        "server": server.strip(),
        "kubeconfig_sources": list(kubeconfig_sources),
        "default_namespace": default_namespace.strip() if isinstance(default_namespace, str) else None,
        "status": status,
        "last_validated_at": None,
        "last_error": None,
        "created_at": now,
        "updated_at": now
    }
    contexts.append(row)
    _save("k8s_contexts.json", contexts)
    return {"context": row}

def k8s_update_context(id, context_name=None, cluster_name=None, user_name=None, server=None, kubeconfig_sources=None, default_namespace=None, status=None, last_error=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", error_code="INVALID_ID")

    contexts = _load("k8s_contexts.json")
    idx = None
    for i, c in enumerate(contexts):
        if c.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "context not found", error_code="CONTEXT_NOT_FOUND")

    row = contexts[idx]

    # Validate incoming fields
    if context_name is not None:
        if not isinstance(context_name, str) or not context_name.strip():
            return _err("VALIDATION_ERROR", "context_name must be a non-empty string when provided", error_code="INVALID_CONTEXT_NAME")
        # uniqueness
        for c in contexts:
            if c.get("id") != id and c.get("context_name") == context_name:
                return _err("CONFLICT", "context_name would collide with an existing registration", error_code="CONTEXT_NAME_EXISTS")

    if cluster_name is not None and (not isinstance(cluster_name, str) or not cluster_name.strip()):
        return _err("VALIDATION_ERROR", "cluster_name must be a non-empty string when provided", error_code="INVALID_CLUSTER_NAME")
    if user_name is not None and (not isinstance(user_name, str) or not user_name.strip()):
        return _err("VALIDATION_ERROR", "user_name must be a non-empty string when provided", error_code="INVALID_USER_NAME")
    if server is not None:
        if not isinstance(server, str) or not server.strip():
            return _err("VALIDATION_ERROR", "server must be a non-empty string when provided", error_code="INVALID_SERVER")
        s = server.strip()
        if not (s.startswith("https://") or s.startswith("http://")):
            return _err("VALIDATION_ERROR", "server must start with http:// or https://", error_code="INVALID_SERVER")

    if kubeconfig_sources is not None:
        if not isinstance(kubeconfig_sources, list) or len(kubeconfig_sources) < 1:
            return _err("VALIDATION_ERROR", "kubeconfig_sources must be a non-empty array when provided", error_code="INVALID_KUBECONFIG_SOURCES")
        allowed_sources = {"file", "env", "secret", "inline"}
        for i, src in enumerate(kubeconfig_sources):
            if not isinstance(src, str) or src not in allowed_sources:
                return _err("VALIDATION_ERROR", f"kubeconfig_sources[{i}] must be one of: file, env, secret, inline", error_code="INVALID_KUBECONFIG_SOURCES")

    if default_namespace is not None and (not isinstance(default_namespace, str) or not default_namespace.strip()):
        return _err("VALIDATION_ERROR", "default_namespace must be a non-empty string when provided", error_code="INVALID_DEFAULT_NAMESPACE")

    if last_error is not None and (not isinstance(last_error, str)):
        return _err("VALIDATION_ERROR", "last_error must be a string when provided", error_code="INVALID_LAST_ERROR")

    # Lifecycle transition validation
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error", error_code="INVALID_STATUS")
        current = row.get("status")
        transitions = {
            "active": {"disabled", "error"},
            "disabled": {"active"},
            "error": {"active", "disabled"}
        }
        if current not in transitions:
            return _err("VALIDATION_ERROR", "existing context has invalid status", error_code="INVALID_STATUS")
        if status != current and status not in transitions[current]:
            return _err("INVALID_TRANSITION", f"illegal status transition from {current} to {status}", error_code="ILLEGAL_STATUS_TRANSITION")

    # Apply updates
    changed = False
    if context_name is not None and context_name != row.get("context_name"):
        row["context_name"] = context_name
        changed = True
    if cluster_name is not None and cluster_name != row.get("cluster_name"):
        row["cluster_name"] = cluster_name
        changed = True
    if user_name is not None and user_name != row.get("user_name"):
        row["user_name"] = user_name
        changed = True
    if server is not None and server != row.get("server"):
        row["server"] = server
        changed = True
    if kubeconfig_sources is not None and kubeconfig_sources != row.get("kubeconfig_sources"):
        row["kubeconfig_sources"] = kubeconfig_sources
        changed = True
    if default_namespace is not None and default_namespace != row.get("default_namespace"):
        row["default_namespace"] = default_namespace
        changed = True
    if status is not None and status != row.get("status"):
        row["status"] = status
        changed = True
    if last_error is not None and last_error != row.get("last_error"):
        row["last_error"] = last_error
        changed = True

    if not changed:
        # No success without effect: treat as NOT_FOUND-equivalent for update? Better VALIDATION_ERROR for no-op.
        return _err("VALIDATION_ERROR", "no changes supplied", error_code="NO_CHANGES")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row["updated_at"] = now
    contexts[idx] = row
    _save("k8s_contexts.json", contexts)

    return {"context": row}

def k8s_get_operations(context_id=None, context=None, status=None, tool_name=None, is_mutation=None, namespace=None, resource_type=None, resource_name=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate filters
    if context_id is not None and (not isinstance(context_id, str) or not context_id.strip()):
        return _err("VALIDATION_ERROR", "context_id must be a non-empty string when provided", error_code="INVALID_CONTEXT_ID")
    if context is not None and (not isinstance(context, str) or not context.strip()):
        return _err("VALIDATION_ERROR", "context must be a non-empty string when provided", error_code="INVALID_CONTEXT")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled", error_code="INVALID_STATUS")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided", error_code="INVALID_TOOL_NAME")
    if is_mutation is not None and not isinstance(is_mutation, bool):
        return _err("VALIDATION_ERROR", "is_mutation must be a boolean when provided", error_code="INVALID_IS_MUTATION")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string when provided", error_code="INVALID_NAMESPACE")
    if resource_type is not None and (not isinstance(resource_type, str) or not resource_type.strip()):
        return _err("VALIDATION_ERROR", "resource_type must be a non-empty string when provided", error_code="INVALID_RESOURCE_TYPE")
    if resource_name is not None and (not isinstance(resource_name, str) or not resource_name.strip()):
        return _err("VALIDATION_ERROR", "resource_name must be a non-empty string when provided", error_code="INVALID_RESOURCE_NAME")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", error_code="INVALID_LIMIT")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "started_at", "finished_at", "status", "tool_name"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, started_at, finished_at, status, tool_name", error_code="INVALID_SORT")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", error_code="INVALID_ORDER")

    # Resolve context name -> context_id if provided
    contexts = _load("k8s_contexts.json")
    context_name_to_id = {c.get("context_name"): c.get("id") for c in contexts if isinstance(c, dict)}
    if context is not None:
        cid = context_name_to_id.get(context)
        if cid is None:
            # reads with filters matching nothing return empty set
            return {"operations": [], "total": 0, "limit": limit, "has_more": False, "next_cursor": None}
        if context_id is not None and context_id != cid:
            return {"operations": [], "total": 0, "limit": limit, "has_more": False, "next_cursor": None}
        context_id = cid

    ops = _load("k8s_operations.json")
    if not isinstance(ops, list):
        ops = []

    def _match(o):
        if not isinstance(o, dict):
            return False
        if context_id is not None and o.get("context_id") != context_id:
            return False
        if status is not None and o.get("status") != status:
            return False
        if tool_name is not None and o.get("tool_name") != tool_name:
            return False
        if is_mutation is not None and o.get("is_mutation") != is_mutation:
            return False
        if namespace is not None and o.get("requested_namespace") != namespace:
            return False
        if resource_type is not None and o.get("resource_type") != resource_type:
            return False
        if resource_name is not None and o.get("resource_name") != resource_name:
            return False
        return True

    filtered = [o for o in ops if _match(o)]

    # Sorting: treat None as minimal for asc, maximal for desc by using tuple key
    def _key(o):
        v = o.get(sort)
        # Normalize ISO-ish timestamps and strings
        if v is None:
            return (1, "")
        if isinstance(v, (int, float)):
            return (0, v)
        if isinstance(v, str):
            return (0, v)
        return (0, str(v))

    reverse = (order == "desc")
    filtered.sort(key=_key, reverse=reverse)

    # Cursor: opaque base64 of integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", error_code="INVALID_CURSOR")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "cursor is invalid", error_code="INVALID_CURSOR")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid", error_code="INVALID_CURSOR")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid", error_code="INVALID_CURSOR")

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_off}".encode("utf-8")).decode("utf-8")

    return {
        "operations": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

