def k8s_cancel_operation(id, reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0199000" if __import__("os").path.isdir("./environment_mix/0199000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", error_code="VALIDATION_ERROR", field="id")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided", error_code="VALIDATION_ERROR", field="reason")

    ops = _load("k8s_operations.json")
    if not isinstance(ops, list):
        ops = []
    op = None
    for r in ops:
        if isinstance(r, dict) and r.get("id") == id:
            op = r
            break
    if op is None:
        return _err("NOT_FOUND", "Operation not found", error_code="NOT_FOUND", id=id)

    # Ambient auth: if any active key exists, allow cancellation; otherwise unauthorized.
    keys = _load("api_keys.json")
    any_active = any(isinstance(k, dict) and k.get("status") == "active" for k in keys)
    if not any_active:
        return _err("UNAUTHORIZED", "No active API key available to authorize cancellation", error_code="UNAUTHORIZED")

    # Enforce lifecycle transitions
    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": []
    }
    cur = op.get("status")
    if cur not in transitions:
        return _err("VALIDATION_ERROR", "Operation has invalid status", error_code="VALIDATION_ERROR", status=cur)
    if "cancelled" not in transitions[cur]:
        return _err("INVALID_TRANSITION", "Operation cannot be cancelled from its current status", error_code="INVALID_TRANSITION", status=cur)

    # Perform transition
    op["status"] = "cancelled"
    if not op.get("started_at"):
        op["started_at"] = now
    op["finished_at"] = now
    op["updated_at"] = now
    # attach reason for audit in error_message (best available field)
    if isinstance(reason, str) and reason.strip():
        op["error_code"] = op.get("error_code") or "CANCELLED"
        op["error_message"] = f"Cancelled: {reason.strip()}"
    else:
        op["error_code"] = op.get("error_code") or "CANCELLED"
        op["error_message"] = op.get("error_message") or "Cancelled"

    _save("k8s_operations.json", ops)

    # Cascade delete results for this operation if they exist (on delete cascade is schema rule; cancellation does not delete)
    latency_ms = int((time.time() - t0) * 1000)
    return {"operation": op, "latency_ms": latency_ms}
